import React, { useState } from 'react';
import { getGeminiApiKey, setGeminiApiKey } from './geminiClient';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { KeyRound, ExternalLink, CheckCircle, AlertCircle } from 'lucide-react';

export default function GeminiKeySetup({ onSaved }) {
  const [key, setKey] = useState('');
  const [saved, setSaved] = useState(!!getGeminiApiKey());

  const handleSave = () => {
    setGeminiApiKey(key.trim());
    setSaved(true);
    onSaved?.();
  };

  const handleRemove = () => {
    setGeminiApiKey('');
    setKey('');
    setSaved(false);
  };

  if (saved) {
    return (
      <Card className="border-green-200 bg-green-50">
        <CardContent className="p-4 flex items-center justify-between">
          <div className="flex items-center gap-2 text-green-700">
            <CheckCircle className="w-4 h-4" />
            <span className="text-sm font-medium">Gemini API key configured</span>
          </div>
          <Button size="sm" variant="ghost" onClick={handleRemove} className="text-red-600 hover:text-red-700">
            Remove Key
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-amber-200 bg-amber-50">
      <CardContent className="p-4 space-y-3">
        <div className="flex items-center gap-2 text-amber-800">
          <AlertCircle className="w-4 h-4" />
          <span className="text-sm font-medium">Gemini API key required for AI features</span>
        </div>
        <div className="space-y-2">
          <Label className="text-xs text-amber-700">
            Get your free API key at{' '}
            <a
              href="https://aistudio.google.com/apikey"
              target="_blank"
              rel="noopener noreferrer"
              className="underline inline-flex items-center gap-1"
            >
              aistudio.google.com
              <ExternalLink className="w-3 h-3" />
            </a>
          </Label>
          <div className="flex gap-2">
            <Input
              type="password"
              placeholder="Paste your Gemini API key..."
              value={key}
              onChange={(e) => setKey(e.target.value)}
              className="bg-white text-sm"
            />
            <Button size="sm" onClick={handleSave} disabled={!key.trim()}>
              <KeyRound className="w-4 h-4 mr-1" />
              Save
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

src/components/ai/ProductionAssistant.js:
import React, { useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { callGemini, hasGeminiApiKey } from './geminiClient';
import GeminiKeySetup from './GeminiKeySetup';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Sparkles, Loader2, FileText, BookOpen, Theater, Copy, Check } from 'lucide-react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

export default function ProductionAssistant({ production }) {
  const [prompt, setPrompt] = useState('');
  const [activeTab, setActiveTab] = useState('knowledge');
  const [result, setResult] = useState(null);
  const [copied, setCopied] = useState(false);

  const generateMutation = useMutation({
    mutationFn: async ({ type, customPrompt }) => {
      let systemPrompt = '';
      let schema = null;

      if (type === 'knowledge') {
        systemPrompt = `You are an expert production knowledge curator. Based on the production "${production.name}" and user request: "${customPrompt}", create a comprehensive knowledge base article.`;
        schema = {
          type: 'object',
          properties: {
            title: { type: 'string' },
            content: { type: 'string' },
            tags: { type: 'array', items: { type: 'string' } },
            category: { type: 'string', enum: ['safety', 'best_practice', 'technical', 'troubleshooting', 'equipment', 'process'] }
          }
        };
      } else if (type === 'procedure') {
        systemPrompt = `You are an expert production procedure writer. Based on the production "${production.name}" and user request: "${customPrompt}", create a detailed step-by-step procedure.`;
        schema = {
          type: 'object',
          properties: {
            procedure_name: { type: 'string' },
            description: { type: 'string' },
            steps: { type: 'array', items: { type: 'object', properties: { step_number: { type: 'number' }, description: { type: 'string' } } } },
            safety_notes: { type: 'string' },
            required_equipment: { type: 'array', items: { type: 'string' } }
          }
        };
      } else if (type === 'cuedoc') {
        systemPrompt = `You are an expert stage manager. Based on the production "${production.name}" and user request: "${customPrompt}", create a comprehensive cue documentation.`;
        schema = {
          type: 'object',
          properties: {
            title: { type: 'string' },
            act_scene: { type: 'string' },
            cues: { type: 'array', items: { type: 'object', properties: { cue_number: { type: 'string' }, cue_type: { type: 'string' }, description: { type: 'string' }, timing_notes: { type: 'string' } } } }
          }
        };
      } else if (type === 'suggestions') {
        systemPrompt = `You are a production expert advisor. Analyze the production "${production.name}" with description: "${production.description || 'No description'}". Provide actionable suggestions for: task planning, crew assignments, risk mitigation, and production optimization.`;
        schema = {
          type: 'object',
          properties: {
            task_suggestions: { type: 'array', items: { type: 'string' } },
            crew_recommendations: { type: 'array', items: { type: 'string' } },
            risk_alerts: { type: 'array', items: { type: 'string' } },
            optimization_tips: { type: 'array', items: { type: 'string' } }
          }
        };
      }

      const response = await callGemini(systemPrompt, schema);

      return { type, data: response };
    },
    onSuccess: (data) => {
      setResult(data);
      setPrompt('');
    }
  });

  const handleCopy = async (text) => {
    await navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="space-y-4">
      <GeminiKeySetup />
      <Card className="border-purple-200 bg-purple-50">
        <CardHeader>
          <div className="flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-purple-600" />
            <CardTitle>AI Production Assistant</CardTitle>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <TabsList className="grid grid-cols-4 w-full">
              <TabsTrigger value="knowledge">
                <BookOpen className="w-4 h-4 mr-2" />
                Knowledge
              </TabsTrigger>
              <TabsTrigger value="procedure">
                <FileText className="w-4 h-4 mr-2" />
                Procedure
              </TabsTrigger>
              <TabsTrigger value="cuedoc">
                <Theater className="w-4 h-4 mr-2" />
                Cue Doc
              </TabsTrigger>
              <TabsTrigger value="suggestions">
                <Sparkles className="w-4 h-4 mr-2" />
                Suggestions
              </TabsTrigger>
            </TabsList>

            <TabsContent value="knowledge" className="space-y-3">
              <Textarea
                placeholder="E.g., 'Create an article about proper lighting safety protocols for this production'"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                rows={3}
              />
              <Button 
                onClick={() => generateMutation.mutate({ type: 'knowledge', customPrompt: prompt })}
                disabled={!prompt.trim() || generateMutation.isPending}
                className="w-full"
              >
                {generateMutation.isPending ? (
                  <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Generating...</>
                ) : (
                  <><Sparkles className="w-4 h-4 mr-2" /> Generate Knowledge Article</>
                )}
              </Button>
            </TabsContent>

            <TabsContent value="procedure" className="space-y-3">
              <Textarea
                placeholder="E.g., 'Create a procedure for daily sound check and equipment setup'"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                rows={3}
              />
              <Button 
                onClick={() => generateMutation.mutate({ type: 'procedure', customPrompt: prompt })}
                disabled={!prompt.trim() || generateMutation.isPending}
                className="w-full"
              >
                {generateMutation.isPending ? (
                  <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Generating...</>
                ) : (
                  <><Sparkles className="w-4 h-4 mr-2" /> Generate Procedure</>
                )}
              </Button>
            </TabsContent>

            <TabsContent value="cuedoc" className="space-y-3">
              <Textarea
                placeholder="E.g., 'Generate lighting cues for Act 1, Scene 2 - bedroom scene at dawn'"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                rows={3}
              />
              <Button 
                onClick={() => generateMutation.mutate({ type: 'cuedoc', customPrompt: prompt })}
                disabled={!prompt.trim() || generateMutation.isPending}
                className="w-full"
              >
                {generateMutation.isPending ? (
                  <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Generating...</>
                ) : (
                  <><Sparkles className="w-4 h-4 mr-2" /> Generate Cue Documentation</>
                )}
              </Button>
            </TabsContent>

            <TabsContent value="suggestions" className="space-y-3">
              <p className="text-sm text-muted-foreground">
                Get AI-powered suggestions for optimizing your production based on current status and setup.
              </p>
              <Button 
                onClick={() => generateMutation.mutate({ type: 'suggestions', customPrompt: '' })}
                disabled={generateMutation.isPending}
                className="w-full"
              >
                {generateMutation.isPending ? (
                  <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Analyzing...</>
                ) : (
                  <><Sparkles className="w-4 h-4 mr-2" /> Get Production Suggestions</>
                )}
              </Button>
            </TabsContent>
          </Tabs>

          {/* Results */}
          {result && (
            <Card className="mt-4 border-purple-200">
              <CardContent className="p-4 space-y-3">
                {result.type === 'knowledge' && (
                  <>
                    <div className="flex items-center justify-between">
                      <h4 className="font-semibold text-lg">{result.data.title}</h4>
                      <Button size="sm" variant="ghost" onClick={() => handleCopy(JSON.stringify(result.data, null, 2))}>
                        {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                      </Button>
                    </div>
                    <Badge>{result.data.category}</Badge>
                    <p className="text-sm whitespace-pre-wrap">{result.data.content}</p>
                    <div className="flex flex-wrap gap-2 mt-2">
                      {result.data.tags?.map((tag, i) => (
                        <Badge key={i} variant="outline">{tag}</Badge>
                      ))}
                    </div>
                  </>
                )}

                {result.type === 'procedure' && (
                  <>
                    <div className="flex items-center justify-between">
                      <h4 className="font-semibold text-lg">{result.data.procedure_name}</h4>
                      <Button size="sm" variant="ghost" onClick={() => handleCopy(JSON.stringify(result.data, null, 2))}>
                        {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                      </Button>
                    </div>
                    <p className="text-sm text-muted-foreground">{result.data.description}</p>
                    <div className="space-y-2 mt-3">
                      {result.data.steps?.map((step, i) => (
                        <div key={i} className="flex gap-3">
                          <div className="w-6 h-6 rounded-full bg-purple-100 text-purple-700 flex items-center justify-center text-xs font-semibold flex-shrink-0">
                            {step.step_number}
                          </div>
                          <p className="text-sm">{step.description}</p>
                        </div>
                      ))}
                    </div>
                    {result.data.safety_notes && (
                      <div className="mt-3 p-3 bg-amber-50 border border-amber-200 rounded-lg">
                        <p className="text-xs font-semibold text-amber-900 mb-1">Safety Notes:</p>
                        <p className="text-sm text-amber-800">{result.data.safety_notes}</p>
                      </div>
                    )}
                  </>
                )}

                {result.type === 'cuedoc' && (
                  <>
                    <div className="flex items-center justify-between">
                      <h4 className="font-semibold text-lg">{result.data.title}</h4>
                      <Button size="sm" variant="ghost" onClick={() => handleCopy(JSON.stringify(result.data, null, 2))}>
                        {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                      </Button>
                    </div>
                    <Badge>{result.data.act_scene}</Badge>
                    <div className="space-y-2 mt-3">
                      {result.data.cues?.map((cue, i) => (
                        <div key={i} className="border-l-4 border-purple-400 pl-3 py-1">
                          <div className="flex items-center gap-2">
                            <Badge variant="outline">{cue.cue_number}</Badge>
                            <span className="text-xs font-semibold">{cue.cue_type}</span>
                          </div>
                          <p className="text-sm mt-1">{cue.description}</p>
                          {cue.timing_notes && (
                            <p className="text-xs text-muted-foreground mt-1">{cue.timing_notes}</p>
                          )}
                        </div>
                      ))}
                    </div>
                  </>
                )}

                {result.type === 'suggestions' && (
                  <>
                    <h4 className="font-semibold text-lg">Production Optimization Suggestions</h4>

                    {result.data.task_suggestions?.length > 0 && (
                      <div>
                        <p className="text-sm font-semibold mb-2">📋 Task Planning:</p>
                        <ul className="space-y-1 ml-4">
                          {result.data.task_suggestions.map((item, i) => (
                            <li key={i} className="text-sm list-disc">{item}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {result.data.crew_recommendations?.length > 0 && (
                      <div>
                        <p className="text-sm font-semibold mb-2">👥 Crew Assignments:</p>
                        <ul className="space-y-1 ml-4">
                          {result.data.crew_recommendations.map((item, i) => (
                            <li key={i} className="text-sm list-disc">{item}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {result.data.risk_alerts?.length > 0 && (
                      <div className="bg-amber-50 border border-amber-200 rounded p-3">
                        <p className="text-sm font-semibold mb-2">⚠️ Risk Alerts:</p>
                        <ul className="space-y-1 ml-4">
                          {result.data.risk_alerts.map((item, i) => (
                            <li key={i} className="text-sm list-disc text-amber-900">{item}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {result.data.optimization_tips?.length > 0 && (
                      <div>
                        <p className="text-sm font-semibold mb-2">💡 Optimization Tips:</p>
                        <ul className="space-y-1 ml-4">
                          {result.data.optimization_tips.map((item, i) => (
                            <li key={i} className="text-sm list-disc">{item}</li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </>
                )}
              </CardContent>
            </Card>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

src/components/ai/SchedulingOptimizer.js:
import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useQuery, useMutation } from '@tanstack/react-query';
import { callGemini } from './geminiClient';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Sparkles, Loader2, Calendar, Users, AlertTriangle, CheckCircle2, TrendingUp } from 'lucide-react';
import { format } from 'date-fns';

export default function SchedulingOptimizer({ production }) {
  const [analysis, setAnalysis] = useState(null);

  const { data: tasks = [] } = useQuery({
    queryKey: ['tasks', production.id],
    queryFn: () => base44.entities.TaskChecklist.filter({ production_id: production.id }),
  });

  const { data: crewAssignments = [] } = useQuery({
    queryKey: ['assignments', production.id],
    queryFn: () => base44.entities.CrewAssignment.filter({ production_id: production.id }),
  });

  const { data: crewMembers = [] } = useQuery({
    queryKey: ['crewMembers'],
    queryFn: () => base44.entities.CrewMember.list(),
  });

  const analyzeMutation = useMutation({
    mutationFn: async () => {
      // Build context for AI
      const crewData = crewMembers.map(cm => {
        const skills = cm.skills ? cm.skills.split(',').map(s => s.trim()) : [];
        const skillLevels = cm.skill_levels ? JSON.parse(cm.skill_levels) : {};
        const assignments = crewAssignments.filter(a => a.crew_member_id === cm.id);
        const blockedDates = cm.blocked_dates ? JSON.parse(cm.blocked_dates) : [];

        return {
          name: cm.full_name,
          role: cm.primary_role,
          skills,
          skillLevels,
          availability: cm.status === 'active',
          blockedDates,
          currentAssignments: assignments.length,
          maxHoursPerWeek: cm.max_hours_per_week
        };
      });

      const taskData = tasks.map(t => {
        const dependencies = t.depends_on ? JSON.parse(t.depends_on) : [];
        return {
          name: t.task_name,
          status: t.completion_status,
          priority: t.priority,
          assignedTo: t.assigned_to,
          dueDate: t.due_date,
          category: t.category,
          estimatedHours: t.estimated_hours,
          dependencies,
          isRecurring: t.is_recurring
        };
      });

      const prompt = `Analyze this production scheduling scenario:

Production: ${production.name}
Status: ${production.status}
Timeline: ${production.start_date ? format(new Date(production.start_date), 'MMM d') : 'TBD'} to ${production.end_date ? format(new Date(production.end_date), 'MMM d') : 'TBD'}

Available Crew (${crewData.length}):
${JSON.stringify(crewData, null, 2)}

Tasks (${taskData.length}):
${JSON.stringify(taskData, null, 2)}

Provide:
1. Task assignment recommendations (match crew skills to unassigned tasks)
2. Schedule optimization suggestions (reorder tasks, identify critical path)
3. Risk identification (crew conflicts, availability issues, dependency bottlenecks)
4. Workload balancing recommendations`;

      const response = await callGemini(prompt, {
        type: 'object',
        properties: {
          task_assignments: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                task_name: { type: 'string' },
                recommended_assignee: { type: 'string' },
                reason: { type: 'string' },
                confidence: { type: 'string', enum: ['high', 'medium', 'low'] }
              }
            }
          },
          schedule_optimizations: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                recommendation: { type: 'string' },
                impact: { type: 'string', enum: ['high', 'medium', 'low'] },
                priority: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] }
              }
            }
          },
          identified_risks: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                risk: { type: 'string' },
                severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
                mitigation: { type: 'string' }
              }
            }
          },
          workload_insights: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                crew_member: { type: 'string' },
                status: { type: 'string', enum: ['overloaded', 'balanced', 'underutilized'] },
                suggestion: { type: 'string' }
              }
            }
          },
          critical_path_tasks: {
            type: 'array',
            items: { type: 'string' }
          }
        }
      });

      return response;
    },
    onSuccess: (data) => {
      setAnalysis(data);
    }
  });

  const confidenceColors = {
    high: 'bg-green-100 text-green-700',
    medium: 'bg-yellow-100 text-yellow-700',
    low: 'bg-red-100 text-red-700'
  };

  const severityColors = {
    critical: 'bg-red-100 text-red-700',
    high: 'bg-orange-100 text-orange-700',
    medium: 'bg-yellow-100 text-yellow-700',
    low: 'bg-blue-100 text-blue-700'
  };

  const statusColors = {
    overloaded: 'bg-red-100 text-red-700',
    balanced: 'bg-green-100 text-green-700',
    underutilized: 'bg-blue-100 text-blue-700'
  };

  return (
    <Card className="border-blue-200 bg-blue-50">
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-blue-600" />
            <CardTitle>AI Scheduling Optimizer</CardTitle>
          </div>
          <Button 
            onClick={() => analyzeMutation.mutate()}
            disabled={analyzeMutation.isPending || tasks.length === 0}
            size="sm"
          >
            {analyzeMutation.isPending ? (
              <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Analyzing...</>
            ) : (
              <><Sparkles className="w-4 h-4 mr-2" /> Optimize Schedule</>
            )}
          </Button>
        </div>
      </CardHeader>

      {analysis && (
        <CardContent className="space-y-4">
          {/* Task Assignments */}
          {analysis.task_assignments?.length > 0 && (
            <div>
              <h4 className="font-semibold mb-3 flex items-center gap-2">
                <Users className="w-4 h-4" />
                Recommended Task Assignments ({analysis.task_assignments.length})
              </h4>
              <ScrollArea className="h-48">
                <div className="space-y-2">
                  {analysis.task_assignments.map((item, i) => (
                    <Card key={i}>
                      <CardContent className="p-3">
                        <div className="flex items-start justify-between gap-2">
                          <div className="flex-1">
                            <p className="font-medium text-sm">{item.task_name}</p>
                            <p className="text-xs text-muted-foreground mt-1">
                              → Assign to: <span className="font-medium text-blue-600">{item.recommended_assignee}</span>
                            </p>
                            <p className="text-xs text-muted-foreground mt-1">{item.reason}</p>
                          </div>
                          <Badge className={confidenceColors[item.confidence]}>{item.confidence}</Badge>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </ScrollArea>
            </div>
          )}

          {/* Schedule Optimizations */}
          {analysis.schedule_optimizations?.length > 0 && (
            <div>
              <h4 className="font-semibold mb-3 flex items-center gap-2">
                <TrendingUp className="w-4 h-4" />
                Schedule Optimizations
              </h4>
              <div className="space-y-2">
                {analysis.schedule_optimizations.map((item, i) => (
                  <Card key={i} className="border-l-4 border-l-blue-500">
                    <CardContent className="p-3">
                      <div className="flex items-start justify-between gap-2">
                        <p className="text-sm flex-1">{item.recommendation}</p>
                        <div className="flex gap-1">
                          <Badge variant="outline">{item.impact} impact</Badge>
                          <Badge className={severityColors[item.priority]}>{item.priority}</Badge>
                        </div>
