  FileText,
  Download,
  Printer,
  Loader2,
  Sparkles,
  Users,
  ListTodo,
  AlertTriangle,
  Wrench,
  ClipboardList,
  CheckCircle2
} from 'lucide-react';

const departmentLabels = {
