import React, { useState, useEffect } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Loader2 } from 'lucide-react';

const initialFormState = {
  asset_name: '',
  category: '',
  serial_number: '',
  status: 'available',
  location_id: '',
  purchase_date: '',
  notes: '',
};

const categories = [
  { value: 'lighting', label: 'Lighting' },
  { value: 'sound', label: 'Sound' },
  { value: 'rigging', label: 'Rigging' },
  { value: 'staging', label: 'Staging' },
  { value: 'video', label: 'Video' },
  { value: 'props', label: 'Props' },
  { value: 'tools', label: 'Tools' },
  { value: 'safety', label: 'Safety' },
  { value: 'other', label: 'Other' },
];

export default function EquipmentForm({ open, onClose, asset, locations = [] }) {
  const [formData, setFormData] = useState(initialFormState);
  const queryClient = useQueryClient();

  useEffect(() => {
    if (asset) {
      setFormData({
        asset_name: asset.asset_name || '',
        category: asset.category || '',
        serial_number: asset.serial_number || '',
        status: asset.status || 'available',
        location_id: asset.location_id || '',
        purchase_date: asset.purchase_date || '',
        notes: asset.notes || '',
      });
    } else {
      setFormData(initialFormState);
    }
  }, [asset, open]);

  const createMutation = useMutation({
    mutationFn: (data) => base44.entities.EquipmentAsset.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['equipment'] });
      onClose();
    },
  });

  const updateMutation = useMutation({
    mutationFn: (data) => base44.entities.EquipmentAsset.update(asset.id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['equipment'] });
      onClose();
    },
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    const data = { ...formData };
    if (!data.location_id) delete data.location_id;

    if (asset) {
      updateMutation.mutate(data);
    } else {
      createMutation.mutate(data);
    }
  };

  const isLoading = createMutation.isPending || updateMutation.isPending;

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>
            {asset ? 'Edit Equipment' : 'Add Equipment'}
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="asset_name">Asset Name *</Label>
            <Input
              id="asset_name"
              value={formData.asset_name}
              onChange={(e) => setFormData({ ...formData, asset_name: e.target.value })}
              placeholder="Enter asset name"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="category">Category *</Label>
              <Select
                value={formData.category}
                onValueChange={(value) => setFormData({ ...formData, category: value })}
                required
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select" />
                </SelectTrigger>
                <SelectContent>
                  {categories.map((cat) => (
                    <SelectItem key={cat.value} value={cat.value}>
                      {cat.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="status">Status</Label>
              <Select
                value={formData.status}
                onValueChange={(value) => setFormData({ ...formData, status: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="available">Available</SelectItem>
                  <SelectItem value="in_use">In Use</SelectItem>
                  <SelectItem value="maintenance">Maintenance</SelectItem>
                  <SelectItem value="retired">Retired</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div>
            <Label htmlFor="serial_number">Serial Number</Label>
            <Input
              id="serial_number"
              value={formData.serial_number}
              onChange={(e) => setFormData({ ...formData, serial_number: e.target.value })}
              placeholder="Serial number"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="location_id">Location</Label>
              <Select
                value={formData.location_id}
                onValueChange={(value) => setFormData({ ...formData, location_id: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select" />
                </SelectTrigger>
                <SelectContent>
                  {locations.map((loc) => (
                    <SelectItem key={loc.id} value={loc.id}>
                      {loc.location_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="purchase_date">Purchase Date</Label>
              <Input
                id="purchase_date"
                type="date"
                value={formData.purchase_date}
                onChange={(e) => setFormData({ ...formData, purchase_date: e.target.value })}
              />
            </div>
          </div>

          <div>
            <Label htmlFor="notes">Notes</Label>
            <Textarea
              id="notes"
              value={formData.notes}
              onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
              placeholder="Additional notes..."
              rows={2}
            />
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              {asset ? 'Update' : 'Add'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

src/components/equipment/EquipmentSchedu:
import React, { useState, useEffect } from 'react';
import { useMutation, useQueryClient, useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from '@/components/ui/select';
import { Loader2, AlertTriangle, CheckCircle } from 'lucide-react';

const initialFormState = {
  asset_id: '',
  production_id: '',
  task_id: '',
  start_date: '',
  end_date: '',
  status: 'scheduled',
  notes: '',
  booked_by: '',
};

export default function EquipmentScheduleForm({ 
  open, onClose, schedule, assets = [], productions = [], 
  preSelectedAsset, preSelectedProductionId, checkAvailability 
}) {
  const [formData, setFormData] = useState(initialFormState);
  const [availabilityStatus, setAvailabilityStatus] = useState(null);
  const queryClient = useQueryClient();

  const { data: tasks = [] } = useQuery({
    queryKey: ['productionTasks', formData.production_id],
    queryFn: () => base44.entities.TaskChecklist.filter({ production_id: formData.production_id }),
    enabled: !!formData.production_id,
  });

  useEffect(() => {
    if (schedule) {
      setFormData({
        asset_id: schedule.asset_id || '',
        production_id: schedule.production_id || '',
        task_id: schedule.task_id || '',
        start_date: schedule.start_date || '',
        end_date: schedule.end_date || '',
        status: schedule.status || 'scheduled',
        notes: schedule.notes || '',
        booked_by: schedule.booked_by || '',
      });
    } else {
      setFormData({
        ...initialFormState,
        asset_id: preSelectedAsset?.id || '',
        production_id: preSelectedProductionId || '',
      });
    }
    setAvailabilityStatus(null);
  }, [schedule, open, preSelectedAsset, preSelectedProductionId]);

  useEffect(() => {
    if (formData.asset_id && formData.start_date && formData.end_date && checkAvailability) {
      const isAvailable = checkAvailability(
        formData.asset_id, 
        formData.start_date, 
        formData.end_date,
        schedule?.id
      );
      setAvailabilityStatus(isAvailable);
    } else {
      setAvailabilityStatus(null);
    }
  }, [formData.asset_id, formData.start_date, formData.end_date, checkAvailability, schedule]);

  const createMutation = useMutation({
    mutationFn: (data) => base44.entities.EquipmentSchedule.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['equipmentSchedules'] });
      onClose();
    },
  });

  const updateMutation = useMutation({
    mutationFn: (data) => base44.entities.EquipmentSchedule.update(schedule.id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['equipmentSchedules'] });
      onClose();
    },
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    const data = { ...formData };
    if (!data.task_id) delete data.task_id;

    if (schedule) {
      updateMutation.mutate(data);
    } else {
      createMutation.mutate(data);
    }
  };

  const isLoading = createMutation.isPending || updateMutation.isPending;
  const availableAssets = assets.filter(a => a.status !== 'retired');

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>{schedule ? 'Edit Booking' : 'Book Equipment'}</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="asset_id">Equipment *</Label>
            <Select
              value={formData.asset_id}
              onValueChange={(value) => setFormData({ ...formData, asset_id: value })}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select equipment" />
              </SelectTrigger>
              <SelectContent>
                {availableAssets.map((asset) => (
                  <SelectItem key={asset.id} value={asset.id}>
                    {asset.asset_name} ({asset.category})
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label htmlFor="production_id">Production *</Label>
            <Select
              value={formData.production_id}
              onValueChange={(value) => setFormData({ ...formData, production_id: value, task_id: '' })}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select production" />
              </SelectTrigger>
              <SelectContent>
                {productions.map((prod) => (
                  <SelectItem key={prod.id} value={prod.id}>{prod.name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {tasks.length > 0 && (
            <div>
              <Label htmlFor="task_id">Link to Task (Optional)</Label>
              <Select
                value={formData.task_id}
                onValueChange={(value) => setFormData({ ...formData, task_id: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select task" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value={null}>None</SelectItem>
                  {tasks.map((task) => (
                    <SelectItem key={task.id} value={task.id}>{task.task_name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="start_date">Start Date *</Label>
              <Input
                id="start_date"
                type="date"
                value={formData.start_date}
                onChange={(e) => setFormData({ ...formData, start_date: e.target.value })}
                required
              />
            </div>
            <div>
              <Label htmlFor="end_date">End Date *</Label>
              <Input
                id="end_date"
                type="date"
                value={formData.end_date}
                onChange={(e) => setFormData({ ...formData, end_date: e.target.value })}
                required
              />
            </div>
          </div>

          {availabilityStatus !== null && (
            <div className={`p-3 rounded-lg flex items-center gap-2 ${
              availabilityStatus ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
            }`}>
              {availabilityStatus ? (
                <>
                  <CheckCircle className="w-4 h-4" />
                  <span className="text-sm">Equipment is available for these dates</span>
                </>
              ) : (
                <>
                  <AlertTriangle className="w-4 h-4" />
                  <span className="text-sm">Equipment has conflicting bookings</span>
                </>
              )}
            </div>
          )}

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="status">Status</Label>
              <Select
                value={formData.status}
                onValueChange={(value) => setFormData({ ...formData, status: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="scheduled">Scheduled</SelectItem>
                  <SelectItem value="in_use">In Use</SelectItem>
                  <SelectItem value="returned">Returned</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="booked_by">Booked By</Label>
              <Input
                id="booked_by"
                value={formData.booked_by}
                onChange={(e) => setFormData({ ...formData, booked_by: e.target.value })}
                placeholder="Your name"
              />
            </div>
          </div>

          <div>
            <Label htmlFor="notes">Notes</Label>
            <Textarea
              id="notes"
              value={formData.notes}
              onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
              rows={2}
            />
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <Button type="button" variant="outline" onClick={onClose}>Cancel</Button>
            <Button 
              type="submit" 
              disabled={isLoading || availabilityStatus === false}
            >
              {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              {schedule ? 'Update' : 'Book'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

src/components/incidents/IncidentAIAnaly:
import React, { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { callGemini } from '@/components/ai/geminiClient';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Sparkles, Loader2, Save, RefreshCw, CheckCircle } from 'lucide-react';

export default function IncidentAIAnalysis({ incident, onSaved }) {
  const queryClient = useQueryClient();
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState({
    summary: '',
    root_cause: '',
    corrective_action: '',
    preventative_action: '',
    category: ''
  });
  const [saved, setSaved] = useState(false);

  const { data: historicalIncidents = [] } = useQuery({
    queryKey: ['incidents'],
    queryFn: () => base44.entities.IncidentLog.list('-created_date', 50),
  });

  const { data: existingAnalyses = [] } = useQuery({
    queryKey: ['historical-analyses'],
    queryFn: () => base44.entities.HistoricalIncidentAnalysis.list(),
  });

  const saveMutation = useMutation({
    mutationFn: (data) => base44.entities.HistoricalIncidentAnalysis.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['historical-analyses'] });
      setSaved(true);
      onSaved?.();
    },
  });

  const analyzeIncident = async () => {
    setIsAnalyzing(true);
    setSaved(false);

    const similarIncidents = historicalIncidents
      .filter(i => i.id !== incident.id)
      .slice(0, 20);

    const pastAnalyses = existingAnalyses.slice(0, 10);

    const prompt = `You are a production operations expert analyzing incidents for a stage/production management system.

CURRENT INCIDENT TO ANALYZE:
- Description: ${incident.description}
- Severity: ${incident.severity}
- Resolution Status: ${incident.resolution_status}
- Resolution Notes: ${incident.resolution_notes || 'None provided'}

HISTORICAL INCIDENTS FOR CONTEXT (${similarIncidents.length} recent incidents):
${similarIncidents.map(i => `- [${i.severity}] ${i.description} (Status: ${i.resolution_status})`).join('\n')}

PREVIOUS ROOT CAUSE ANALYSES (${pastAnalyses.length} analyses):
${pastAnalyses.map(a => `- Root Cause: ${a.root_cause}\n  Corrective: ${a.corrective_action}\n  Preventative: ${a.preventative_action}`).join('\n\n')}

Provide:
1. SUMMARY: Brief key details (2-3 sentences)
2. ROOT CAUSE: Likely underlying cause (be specific to production/stage operations)
3. CORRECTIVE ACTION: Immediate steps to fix/resolve
4. PREVENTATIVE ACTION: Long-term measures to prevent recurrence
5. CATEGORY: Auto-categorize as one of: equipment_failure, human_error, safety_violation, communication_breakdown, environmental, process_gap, other

Consider recurring patterns, equipment issues, procedural gaps, and training needs.`;

    const result = await callGemini(prompt, {
      type: 'object',
      properties: {
        summary: { type: 'string' },
        root_cause: { type: 'string' },
        corrective_action: { type: 'string' },
        preventative_action: { type: 'string' },
        category: { type: 'string', enum: ['equipment_failure', 'human_error', 'safety_violation', 'communication_breakdown', 'environmental', 'process_gap', 'other'] }
      },
      required: ['summary', 'root_cause', 'corrective_action', 'preventative_action', 'category'],
    });

    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const handleSave = () => {
    saveMutation.mutate({
      incident_id: incident.id,
      summary: analysis.summary,
      root_cause: analysis.root_cause,
      corrective_action: analysis.corrective_action,
      preventative_action: analysis.preventative_action,
      category: analysis.category,
      analyzed_by: 'AI Assistant',
    });
  };

  const hasAnalysis = analysis.root_cause || analysis.corrective_action || analysis.preventative_action;

  const categoryColors = {
    equipment_failure: 'bg-red-100 text-red-700',
    human_error: 'bg-orange-100 text-orange-700',
    safety_violation: 'bg-red-100 text-red-700',
    communication_breakdown: 'bg-yellow-100 text-yellow-700',
    environmental: 'bg-blue-100 text-blue-700',
    process_gap: 'bg-purple-100 text-purple-700',
    other: 'bg-slate-100 text-slate-700'
  };

  return (
    <Card className="border-blue-200 bg-blue-50/30">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base flex items-center gap-2">
            <Sparkles className="w-4 h-4 text-blue-600" />
            AI Incident Analysis
          </CardTitle>
          <Badge variant="outline" className="text-blue-600 border-blue-300">
            Powered by AI
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {!hasAnalysis ? (
          <div className="text-center py-4">
            <p className="text-sm text-slate-600 mb-4">
              Analyze this incident using AI to generate root cause, corrective actions, and preventative measures based on historical patterns.
            </p>
            <Button onClick={analyzeIncident} disabled={isAnalyzing} className="bg-blue-600 hover:bg-blue-700">
              {isAnalyzing ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Analyzing...
                </>
              ) : (
                <>
                  <Sparkles className="w-4 h-4 mr-2" />
                  Analyze Incident
                </>
              )}
            </Button>
          </div>
        ) : (
          <>
            {analysis.category && (
              <div className="flex items-center gap-2">
                <Label className="text-slate-700">Category:</Label>
                <Badge className={categoryColors[analysis.category]}>
                  {analysis.category.replace('_', ' ')}
                </Badge>
              </div>
            )}
            {analysis.summary && (
              <div>
                <Label className="text-slate-700">Summary</Label>
                <p className="mt-1 text-sm bg-white border rounded-md p-3">{analysis.summary}</p>
              </div>
            )}
            <div>
              <Label className="text-slate-700">Root Cause</Label>
              <Textarea
                value={analysis.root_cause}
                onChange={(e) => setAnalysis({ ...analysis, root_cause: e.target.value })}
                rows={3}
                className="mt-1 bg-white"
              />
            </div>
            <div>
              <Label className="text-slate-700">Corrective Action</Label>
              <Textarea
                value={analysis.corrective_action}
                onChange={(e) => setAnalysis({ ...analysis, corrective_action: e.target.value })}
                rows={3}
                className="mt-1 bg-white"
              />
            </div>
            <div>
              <Label className="text-slate-700">Preventative Action</Label>
              <Textarea
                value={analysis.preventative_action}
                onChange={(e) => setAnalysis({ ...analysis, preventative_action: e.target.value })}
                rows={3}
                className="mt-1 bg-white"
              />
            </div>
            <div className="flex items-center justify-between pt-2">
              <Button variant="outline" size="sm" onClick={analyzeIncident} disabled={isAnalyzing}>
                <RefreshCw className={`w-4 h-4 mr-2 ${isAnalyzing ? 'animate-spin' : ''}`} />
                Re-analyze
              </Button>
              <div className="flex items-center gap-2">
                {saved && (
                  <span className="text-sm text-green-600 flex items-center gap-1">
                    <CheckCircle className="w-4 h-4" />
                    Saved
                  </span>
                )}
                <Button onClick={handleSave} disabled={saveMutation.isPending || saved} size="sm">
                  {saveMutation.isPending ? (
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  ) : (
                    <Save className="w-4 h-4 mr-2" />
                  )}
                  Save Analysis
                </Button>
              </div>
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
}

src/components/incidents/IncidentForm.js:
import React, { useState, useEffect } from 'react';
import { useMutation, useQueryClient, useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Loader2 } from 'lucide-react';
import IncidentAIAnalysis from './IncidentAIAnalysis';
import { notifyIncidentCreated } from '@/components/notifications/NotificationService';

const initialFormState = {
  production_id: '',
  description: '',
  severity: 'medium',
  resolution_status: 'open',
  reported_by: '',
  assigned_to: '',
  resolution_notes: '',
};

export default function IncidentForm({ open, onClose, incident, productions = [], preSelectedProductionId }) {
  const [formData, setFormData] = useState(initialFormState);
  const queryClient = useQueryClient();

  const { data: crewAssignments = [] } = useQuery({
    queryKey: ['crewAssignments'],
    queryFn: () => base44.entities.CrewAssignment.list()
  });

  useEffect(() => {
    if (incident) {
      setFormData({
        production_id: incident.production_id || '',
        description: incident.description || '',
        severity: incident.severity || 'medium',
        resolution_status: incident.resolution_status || 'open',
        reported_by: incident.reported_by || '',
        assigned_to: incident.assigned_to || '',
        resolution_notes: incident.resolution_notes || '',
      });
    } else {
      setFormData({
        ...initialFormState,
        production_id: preSelectedProductionId || '',
      });
    }
  }, [incident, open, preSelectedProductionId]);

  const createMutation = useMutation({
    mutationFn: async (data) => {
      const newIncident = await base44.entities.IncidentLog.create(data);

      // Notify crew members assigned to this production
      if (data.production_id) {
        const production = productions.find(p => p.id === data.production_id);
        const productionCrew = crewAssignments.filter(ca => ca.production_id === data.production_id);
        const crewEmails = productionCrew
          .map(ca => ca.contact_info)
          .filter(email => email && email.includes('@'));

        if (production && crewEmails.length > 0) {
          await notifyIncidentCreated({
            incident: newIncident,
            production,
            notifyEmails: crewEmails
          });
        }
      }

      return newIncident;
    },
    onMutate: async (newIncident) => {
      await queryClient.cancelQueries({ queryKey: ['incidents'] });
      const previousIncidents = queryClient.getQueryData(['incidents', newIncident.production_id]);

      queryClient.setQueryData(['incidents', newIncident.production_id], (old) => [
        ...(old || []),
        { ...newIncident, id: 'temp-' + Date.now(), created_date: new Date().toISOString() }
      ]);

      return { previousIncidents };
    },
    onError: (err, newIncident, context) => {
      queryClient.setQueryData(['incidents', newIncident.production_id], context.previousIncidents);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['incidents'] });
      onClose();
    },
  });

  const updateMutation = useMutation({
    mutationFn: (data) => base44.entities.IncidentLog.update(incident.id, data),
    onMutate: async (updatedIncident) => {
      await queryClient.cancelQueries({ queryKey: ['incidents'] });
      const previousIncidents = queryClient.getQueryData(['incidents', incident.production_id]);

      queryClient.setQueryData(['incidents', incident.production_id], (old) =>
        (old || []).map((i) => i.id === incident.id ? { ...i, ...updatedIncident } : i)
      );

      return { previousIncidents };
    },
    onError: (err, updatedIncident, context) => {
      queryClient.setQueryData(['incidents', incident.production_id], context.previousIncidents);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['incidents'] });
      onClose();
    },
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    const data = { ...formData };
    if (!data.production_id) delete data.production_id;

    if (incident) {
      updateMutation.mutate(data);
    } else {
      createMutation.mutate(data);
    }
  };

  const isLoading = createMutation.isPending || updateMutation.isPending;

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {incident ? 'Edit Incident' : 'Log Incident'}
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="production_id">Production</Label>
            <Select
              value={formData.production_id}
              onValueChange={(value) => setFormData({ ...formData, production_id: value })}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select production" />
              </SelectTrigger>
              <SelectContent>
                {productions.map((prod) => (
                  <SelectItem key={prod.id} value={prod.id}>
                    {prod.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label htmlFor="description">Description *</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              placeholder="Describe the incident..."
              rows={3}
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="severity">Severity *</Label>
              <Select
                value={formData.severity}
                onValueChange={(value) => setFormData({ ...formData, severity: value })}
                required
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="critical">Critical</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
