import React, { useState, useEffect } from 'react';
import { base44 } from '@/api/base44Client';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Bell, Check, CheckCheck, AlertTriangle, AtSign, MessageSquare, ClipboardList, Clapperboard } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator,
} from '@/components/ui/dropdown-menu';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Link } from 'react-router-dom';
import { createPageUrl } from '@/utils';
import moment from 'moment';

const notificationIcons = {
  mention: AtSign,
  incident_created: AlertTriangle,
  task_overdue: ClipboardList,
  task_assigned: ClipboardList,
  production_status_change: Clapperboard,
  new_message: MessageSquare
};

const notificationColors = {
  mention: 'text-blue-500',
  incident_created: 'text-red-500',
  task_overdue: 'text-orange-500',
  task_assigned: 'text-green-500',
  production_status_change: 'text-purple-500',
  new_message: 'text-indigo-500'
};

export default function NotificationBell() {
  const [open, setOpen] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const queryClient = useQueryClient();

  useEffect(() => {
    base44.auth.me().then(setCurrentUser).catch(() => {});
  }, []);

  const { data: notifications = [] } = useQuery({
    queryKey: ['notifications', currentUser?.email],
    queryFn: () => base44.entities.Notification.filter({ user_email: currentUser?.email }, '-created_date', 50),
    enabled: !!currentUser?.email,
    refetchInterval: 30000
  });

  const markReadMutation = useMutation({
    mutationFn: (id) => base44.entities.Notification.update(id, { is_read: true }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['notifications'] })
  });

  const markAllReadMutation = useMutation({
    mutationFn: async () => {
      const unread = notifications.filter(n => !n.is_read);
      await Promise.all(unread.map(n => base44.entities.Notification.update(n.id, { is_read: true })));
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['notifications'] })
  });

  const unreadCount = notifications.filter(n => !n.is_read).length;

  const handleNotificationClick = (notification) => {
    if (!notification.is_read) {
      markReadMutation.mutate(notification.id);
    }
    setOpen(false);
  };

  return (
    <DropdownMenu open={open} onOpenChange={setOpen}>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="icon" className="relative">
          <Bell className="h-5 w-5" />
          {unreadCount > 0 && (
            <Badge className="absolute -top-1 -right-1 h-5 w-5 p-0 flex items-center justify-center text-xs bg-red-500">
              {unreadCount > 9 ? '9+' : unreadCount}
            </Badge>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-80">
        <div className="flex items-center justify-between p-3 border-b">
          <span className="font-semibold">Notifications</span>
          {unreadCount > 0 && (
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-xs h-7"
              onClick={() => markAllReadMutation.mutate()}
            >
              <CheckCheck className="h-3 w-3 mr-1" />
              Mark all read
            </Button>
          )}
        </div>
        <ScrollArea className="h-80">
          {notifications.length === 0 ? (
            <div className="p-4 text-center text-muted-foreground text-sm">
              No notifications yet
            </div>
          ) : (
            notifications.map((notification) => {
              const Icon = notificationIcons[notification.type] || Bell;
              const colorClass = notificationColors[notification.type] || 'text-gray-500';

              return (
                <DropdownMenuItem
                  key={notification.id}
                  className={`p-3 cursor-pointer ${!notification.is_read ? 'bg-blue-50/50' : ''}`}
                  asChild
                >
                  <Link 
                    to={notification.link || '#'} 
                    onClick={() => handleNotificationClick(notification)}
                  >
                    <div className="flex gap-3 w-full">
                      <div className={`mt-0.5 ${colorClass}`}>
                        <Icon className="h-4 w-4" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className={`text-sm ${!notification.is_read ? 'font-medium' : ''}`}>
                          {notification.message}
                        </p>
                        <p className="text-xs text-muted-foreground mt-1">
                          {moment(notification.created_date).fromNow()}
                        </p>
                      </div>
                      {!notification.is_read && (
                        <div className="w-2 h-2 bg-blue-500 rounded-full mt-2" />
                      )}
                    </div>
                  </Link>
                </DropdownMenuItem>
              );
            })
          )}
        </ScrollArea>
        <DropdownMenuSeparator />
        <div className="p-2">
          <Link to={createPageUrl('NotificationSettings')}>
            <Button variant="ghost" size="sm" className="w-full text-xs">
              Notification Settings
            </Button>
          </Link>
        </div>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { base44 } from '@/api/base44Client';

// Helper to create notifications
export async function createNotification({ userEmail, type, message, link, entityType, entityId }) {
  // Check user preferences first
  const prefs = await base44.entities.NotificationPreference.filter({ user_email: userEmail });
  const userPref = prefs[0];

  // If user has preferences set, check if this notification type is enabled
  if (userPref) {
    const prefMap = {
      mention: 'mention_enabled',
      incident_created: 'incident_enabled',
      task_overdue: 'task_overdue_enabled',
      task_assigned: 'task_assigned_enabled',
      production_status_change: 'production_status_enabled',
      new_message: 'message_enabled'
    };

    if (userPref[prefMap[type]] === false) {
      return null; // User has disabled this notification type
    }
  }

  return base44.entities.Notification.create({
    user_email: userEmail,
    type,
    message,
    link,
    entity_type: entityType,
    entity_id: entityId,
    is_read: false
  });
}

// Notify on @mention
export async function notifyMention({ mentionedEmail, authorName, entityType, entityId, entityName }) {
  const linkMap = {
    production: `ProductionDetail?id=${entityId}`,
    task: `Tasks`,
    incident: `Incidents`
  };

  return createNotification({
    userEmail: mentionedEmail,
    type: 'mention',
    message: `${authorName} mentioned you in a ${entityType}: "${entityName}"`,
    link: linkMap[entityType] || '',
    entityType,
    entityId
  });
}

// Notify on new incident
export async function notifyIncidentCreated({ incident, production, notifyEmails }) {
  const notifications = notifyEmails.map(email => 
    createNotification({
      userEmail: email,
      type: 'incident_created',
      message: `New ${incident.severity} incident in "${production.name}": ${incident.description.substring(0, 50)}...`,
      link: `ProductionDetail?id=${production.id}`,
      entityType: 'incident',
      entityId: incident.id
    })
  );

  return Promise.all(notifications);
}

// Notify on task assigned
export async function notifyTaskAssigned({ task, production, assigneeEmail, assignerName }) {
  return createNotification({
    userEmail: assigneeEmail,
    type: 'task_assigned',
    message: `${assignerName} assigned you a task in "${production.name}": ${task.task_name}`,
    link: `ProductionDetail?id=${production.id}`,
    entityType: 'task',
    entityId: task.id
  });
}

// Notify on task overdue
export async function notifyTaskOverdue({ task, production, assigneeEmail }) {
  return createNotification({
    userEmail: assigneeEmail,
    type: 'task_overdue',
    message: `Task overdue in "${production.name}": ${task.task_name}`,
    link: `ProductionDetail?id=${production.id}`,
    entityType: 'task',
    entityId: task.id
  });
}

// Notify on production status change
export async function notifyProductionStatusChange({ production, oldStatus, newStatus, notifyEmails }) {
  const notifications = notifyEmails.map(email =>
    createNotification({
      userEmail: email,
      type: 'production_status_change',
      message: `"${production.name}" status changed from ${oldStatus} to ${newStatus}`,
      link: `ProductionDetail?id=${production.id}`,
      entityType: 'production',
      entityId: production.id
    })
  );

  return Promise.all(notifications);
}

// Notify on new message
export async function notifyNewMessage({ conversation, message, senderName, recipientEmails }) {
  const notifications = recipientEmails.map(email =>
    createNotification({
      userEmail: email,
      type: 'new_message',
      message: `${senderName}: ${message.content.substring(0, 50)}${message.content.length > 50 ? '...' : ''}`,
      link: `Messages?conversation=${conversation.id}`,
      entityType: 'message',
      entityId: message.id
    })
  );

  return Promise.all(notifications);
}

import React, { useState, useEffect } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Loader2 } from 'lucide-react';

const initialFormState = {
  title: '',
  category: '',
  description: '',
  last_reviewed_date: '',
  version: 1,
};

export default function ProcedureForm({ open, onClose, procedure }) {
  const [formData, setFormData] = useState(initialFormState);
  const queryClient = useQueryClient();

  useEffect(() => {
    if (procedure) {
      setFormData({
        title: procedure.title || '',
        category: procedure.category || '',
        description: procedure.description || '',
        last_reviewed_date: procedure.last_reviewed_date || '',
        version: procedure.version || 1,
      });
    } else {
      setFormData({
        ...initialFormState,
        last_reviewed_date: new Date().toISOString().split('T')[0],
      });
    }
  }, [procedure, open]);

  const createMutation = useMutation({
    mutationFn: (data) => base44.entities.ProcedureLibrary.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['procedures'] });
      onClose();
    },
  });

  const updateMutation = useMutation({
    mutationFn: (data) => base44.entities.ProcedureLibrary.update(procedure.id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['procedures'] });
      onClose();
    },
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    const data = { ...formData };

    if (procedure) {
      updateMutation.mutate(data);
    } else {
      createMutation.mutate(data);
    }
  };

  const isLoading = createMutation.isPending || updateMutation.isPending;

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>
            {procedure ? 'Edit Procedure' : 'Add Procedure'}
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="title">Title *</Label>
            <Input
              id="title"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
              placeholder="Procedure title"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="category">Category *</Label>
              <Select
                value={formData.category}
                onValueChange={(value) => setFormData({ ...formData, category: value })}
                required
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="safety">Safety</SelectItem>
                  <SelectItem value="technical">Technical</SelectItem>
                  <SelectItem value="operational">Operational</SelectItem>
                  <SelectItem value="emergency">Emergency</SelectItem>
                  <SelectItem value="maintenance">Maintenance</SelectItem>
                  <SelectItem value="setup">Setup</SelectItem>
                  <SelectItem value="teardown">Teardown</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="version">Version</Label>
              <Input
                id="version"
                type="number"
                min="1"
                value={formData.version}
                onChange={(e) => setFormData({ ...formData, version: parseInt(e.target.value) || 1 })}
              />
            </div>
          </div>

          <div>
            <Label htmlFor="description">Procedure Content</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              placeholder="Procedure steps and instructions..."
              rows={6}
            />
          </div>

          <div>
            <Label htmlFor="last_reviewed_date">Last Reviewed Date</Label>
            <Input
              id="last_reviewed_date"
              type="date"
              value={formData.last_reviewed_date}
              onChange={(e) => setFormData({ ...formData, last_reviewed_date: e.target.value })}
            />
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              {procedure ? 'Update' : 'Add'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

