import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Search, Loader2, Copy } from 'lucide-react';
import { format } from 'date-fns';

export default function TemplateSelector({ open, onClose, onSelectTemplate }) {
  const [searchTerm, setSearchTerm] = useState('');

  const { data: templates = [], isLoading } = useQuery({
    queryKey: ['productionTemplates'],
    queryFn: () => base44.entities.ProductionTemplate.list('-created_date'),
    enabled: open,
  });

  const filteredTemplates = templates.filter(t =>
    t.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    t.description?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectTemplate = (template) => {
    const parsedTemplate = {
      ...template,
      template_tasks: JSON.parse(template.template_tasks || '[]'),
      template_roles: JSON.parse(template.template_roles || '[]'),
      default_settings: JSON.parse(template.default_settings || '{}'),
    };
    onSelectTemplate(parsedTemplate);
    onClose();
  };

  const categoryLabel = (cat) =>
    cat?.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ') || 'Other';

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[600px] max-h-[80vh]">
        <DialogHeader>
          <DialogTitle>Select Template</DialogTitle>
          <DialogDescription>
            Choose a template to use as a starting point for your production
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <Input
              placeholder="Search templates..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10"
            />
          </div>

          {isLoading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="w-6 h-6 animate-spin text-slate-400" />
            </div>
          ) : filteredTemplates.length === 0 ? (
            <div className="text-center py-8">
              <Copy className="w-10 h-10 mx-auto mb-2 text-slate-300" />
              <p className="text-slate-500">
                {searchTerm ? 'No templates match your search' : 'No templates available'}
              </p>
            </div>
          ) : (
            <div className="space-y-2 max-h-[calc(80vh-200px)] overflow-y-auto">
              {filteredTemplates.map((template) => {
                const taskCount = JSON.parse(template.template_tasks || '[]').length;
                const roleCount = JSON.parse(template.template_roles || '[]').length;

                return (
                  <Card key={template.id} className="hover:shadow-md transition-shadow">
                    <CardContent className="p-4">
                      <div className="flex items-start justify-between gap-3">
                        <div className="flex-1 min-w-0">
                          <h3 className="font-semibold text-slate-900">{template.name}</h3>
                          {template.description && (
                            <p className="text-sm text-slate-600 mt-1 line-clamp-2">
                              {template.description}
                            </p>
                          )}
                          <div className="flex gap-2 mt-2 flex-wrap">
                            <Badge variant="outline" className="text-xs">
                              {categoryLabel(template.category)}
                            </Badge>
                            {taskCount > 0 && (
                              <Badge variant="outline" className="text-xs">
                                {taskCount} tasks
                              </Badge>
                            )}
                            {roleCount > 0 && (
                              <Badge variant="outline" className="text-xs">
                                {roleCount} roles
                              </Badge>
                            )}
                            {template.usage_count > 0 && (
                              <Badge variant="outline" className="text-xs text-green-700">
                                Used {template.usage_count} times
                              </Badge>
                            )}
                          </div>
                        </div>
                        <Button
                          onClick={() => handleSelectTemplate(template)}
                          className="bg-blue-600 hover:bg-blue-700 whitespace-nowrap"
                        >
                          Use Template
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

src/components/reports/BudgetAnalysisRep:
import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Loader2, DollarSign, TrendingUp, TrendingDown, AlertTriangle } from 'lucide-react';
import ReportExporter from './ReportExporter';

const COLORS = ['#8b5cf6', '#f59e0b', '#10b981', '#3b82f6', '#ef4444', '#ec4899', '#6366f1', '#14b8a6', '#f97316', '#6b7280'];

const categoryLabels = {
  labor: 'Labor',
  equipment: 'Equipment',
  venue: 'Venue',
  materials: 'Materials',
  transportation: 'Transportation',
  catering: 'Catering',
  marketing: 'Marketing',
  insurance: 'Insurance',
  permits: 'Permits',
  contingency: 'Contingency',
  other: 'Other'
};

export default function BudgetAnalysisReport({ productionId, dateRange }) {
  const { data: productions = [] } = useQuery({
    queryKey: ['productions'],
    queryFn: () => base44.entities.Production.list(),
  });

  const { data: allBudgets = [], isLoading: budgetsLoading } = useQuery({
    queryKey: ['allBudgets'],
    queryFn: () => base44.entities.Budget.list(),
  });

  const { data: allExpenses = [], isLoading: expensesLoading } = useQuery({
    queryKey: ['allExpenses'],
    queryFn: () => base44.entities.BudgetExpense.list(),
  });

  const isLoading = budgetsLoading || expensesLoading;

  // Filter by production if selected
  const budgets = productionId && productionId !== 'all'
    ? allBudgets.filter(b => b.production_id === productionId)
    : allBudgets;

  const expenses = productionId && productionId !== 'all'
    ? allExpenses.filter(e => e.production_id === productionId)
    : allExpenses;

  // Calculate actual amounts for each budget
  const getActualAmount = (budgetId) => {
    return expenses
      .filter(e => e.budget_id === budgetId && e.status !== 'rejected')
      .reduce((sum, e) => sum + (e.amount || 0), 0);
  };

  // Calculate totals
  const totalAllocated = budgets.reduce((sum, b) => sum + (b.allocated_amount || 0), 0);
  const totalActual = budgets.reduce((sum, b) => sum + getActualAmount(b.id), 0);
  const variance = totalAllocated - totalActual;
  const variancePercent = totalAllocated > 0 ? ((variance / totalAllocated) * 100).toFixed(1) : 0;

  // Budget vs Actual by category
  const categoryTotals = {};
  budgets.forEach(b => {
    const cat = b.category;
    if (!categoryTotals[cat]) {
      categoryTotals[cat] = { allocated: 0, actual: 0 };
    }
    categoryTotals[cat].allocated += b.allocated_amount || 0;
    categoryTotals[cat].actual += getActualAmount(b.id);
  });

  const categoryChartData = Object.entries(categoryTotals).map(([cat, totals]) => ({
    name: categoryLabels[cat] || cat,
    Allocated: totals.allocated,
    Actual: totals.actual
  }));

  // Budget allocation pie chart
  const allocationData = Object.entries(categoryTotals)
    .filter(([, totals]) => totals.allocated > 0)
    .map(([cat, totals], idx) => ({
      name: categoryLabels[cat] || cat,
      value: totals.allocated,
      color: COLORS[idx % COLORS.length]
    }));

  // Budget by production
  const productionBudgetData = productions
    .map(prod => {
      const prodBudgets = allBudgets.filter(b => b.production_id === prod.id);
      const allocated = prodBudgets.reduce((sum, b) => sum + (b.allocated_amount || 0), 0);
      const actual = prodBudgets.reduce((sum, b) => sum + getActualAmount(b.id), 0);
      return {
        name: prod.name.substring(0, 15),
        Allocated: allocated,
        Actual: actual
      };
    })
    .filter(p => p.Allocated > 0 || p.Actual > 0);

  // Categories over budget
  const overBudgetCategories = Object.entries(categoryTotals)
    .filter(([, totals]) => totals.actual > totals.allocated)
    .map(([cat, totals]) => ({
      category: categoryLabels[cat] || cat,
      allocated: totals.allocated,
      actual: totals.actual,
      over: totals.actual - totals.allocated
    }));

  // CSV columns
  const budgetDetails = budgets.map(b => ({
    ...b,
    actual: getActualAmount(b.id),
    production_name: productions.find(p => p.id === b.production_id)?.name || 'N/A'
  }));

  const csvColumns = [
    { header: 'Production', key: 'production_name' },
    { header: 'Category', accessor: (b) => categoryLabels[b.category] || b.category },
    { header: 'Allocated', key: 'allocated_amount' },
    { header: 'Actual', key: 'actual' },
    { header: 'Variance', accessor: (b) => (b.allocated_amount || 0) - b.actual },
    { header: 'Status', accessor: (b) => b.actual > b.allocated_amount ? 'Over Budget' : 'On Track' },
  ];

  // PDF sections
  const pdfSections = [
    {
      title: 'Budget Summary',
      type: 'summary',
      items: [
        { label: 'Total Allocated', value: `$${totalAllocated.toLocaleString()}` },
        { label: 'Total Spent', value: `$${totalActual.toLocaleString()}` },
        { label: 'Variance', value: `$${Math.abs(variance).toLocaleString()} ${variance >= 0 ? 'under' : 'over'}` },
        { label: 'Variance %', value: `${variancePercent}%` },
        { label: 'Categories Over Budget', value: overBudgetCategories.length },
      ]
    },
    {
      title: 'Budget by Category',
      type: 'summary',
      items: Object.entries(categoryTotals).map(([cat, totals]) => ({
        label: categoryLabels[cat] || cat,
        value: `$${totals.allocated.toLocaleString()} / $${totals.actual.toLocaleString()}`
      }))
    },
    {
      title: 'Budget Details',
      type: 'table',
      columns: csvColumns.map(c => ({ ...c, width: 30 })),
      data: budgetDetails
    }
  ];

  if (isLoading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-slate-400" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Export Button */}
      <div className="flex justify-end">
        <ReportExporter
          title="Budget Analysis Report"
          csvData={budgetDetails}
          csvColumns={csvColumns}
          pdfSections={pdfSections}
          filename="budget_analysis"
        />
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-100">
                <DollarSign className="w-5 h-5 text-blue-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">${(totalAllocated / 1000).toFixed(0)}k</p>
                <p className="text-xs text-slate-500">Total Budget</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-amber-100">
                <DollarSign className="w-5 h-5 text-amber-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">${(totalActual / 1000).toFixed(0)}k</p>
                <p className="text-xs text-slate-500">Total Spent</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card className={variance >= 0 ? '' : 'border-red-200 bg-red-50/50'}>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-lg ${variance >= 0 ? 'bg-green-100' : 'bg-red-100'}`}>
                {variance >= 0 ? (
                  <TrendingDown className="w-5 h-5 text-green-600" />
                ) : (
                  <TrendingUp className="w-5 h-5 text-red-600" />
                )}
              </div>
              <div>
                <p className={`text-2xl font-bold ${variance >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                  ${(Math.abs(variance) / 1000).toFixed(0)}k
                </p>
                <p className="text-xs text-slate-500">{variance >= 0 ? 'Under Budget' : 'Over Budget'}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-red-100">
                <AlertTriangle className="w-5 h-5 text-red-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">{overBudgetCategories.length}</p>
                <p className="text-xs text-slate-500">Over Budget</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Budget vs Actual by Category</CardTitle>
          </CardHeader>
          <CardContent>
            {categoryChartData.length === 0 ? (
              <p className="text-center py-8 text-slate-500">No budget data</p>
            ) : (
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={categoryChartData}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" tick={{ fontSize: 10 }} angle={-45} textAnchor="end" height={60} />
                    <YAxis tickFormatter={(v) => `$${(v/1000).toFixed(0)}k`} />
                    <Tooltip formatter={(value) => `$${value.toLocaleString()}`} />
                    <Legend />
                    <Bar dataKey="Allocated" fill="#3b82f6" />
                    <Bar dataKey="Actual" fill="#f59e0b" />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Budget Allocation</CardTitle>
          </CardHeader>
          <CardContent>
            {allocationData.length === 0 ? (
              <p className="text-center py-8 text-slate-500">No allocation data</p>
            ) : (
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={allocationData}
                      cx="50%"
                      cy="50%"
                      innerRadius={40}
                      outerRadius={80}
                      dataKey="value"
                      label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                    >
                      {allocationData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(value) => `$${value.toLocaleString()}`} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Production Comparison */}
      {productionBudgetData.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Budget by Production</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={productionBudgetData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="name" />
                  <YAxis tickFormatter={(v) => `$${(v/1000).toFixed(0)}k`} />
                  <Tooltip formatter={(value) => `$${value.toLocaleString()}`} />
                  <Legend />
                  <Bar dataKey="Allocated" fill="#3b82f6" />
                  <Bar dataKey="Actual" fill="#f59e0b" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Category Breakdown Table */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Category Breakdown</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {Object.entries(categoryTotals).map(([cat, totals]) => {
              const percent = totals.allocated > 0 
                ? Math.min((totals.actual / totals.allocated) * 100, 100) 
                : 0;
              const isOver = totals.actual > totals.allocated;

              return (
                <div key={cat} className="space-y-1">
                  <div className="flex justify-between text-sm">
                    <span className="font-medium">{categoryLabels[cat] || cat}</span>
                    <span className={isOver ? 'text-red-600' : 'text-slate-600'}>
                      ${totals.actual.toLocaleString()} / ${totals.allocated.toLocaleString()}
                      {isOver && <Badge className="ml-2 bg-red-100 text-red-700">Over</Badge>}
                    </span>
                  </div>
                  <Progress value={percent} className={isOver ? '[&>div]:bg-red-500' : ''} />
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

src/components/reports/CrewUtilizationRe:
import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Loader2, Users, UserCheck, Calendar, Award } from 'lucide-react';
import ReportExporter from './ReportExporter';

const COLORS = ['#8b5cf6', '#f59e0b', '#10b981', '#3b82f6', '#ef4444', '#ec4899', '#6366f1'];

const roleLabels = {
  stage_manager: 'Stage Manager',
  lighting: 'Lighting',
  sound: 'Sound',
  props: 'Props',
  wardrobe: 'Wardrobe',
  set: 'Set',
  technical_director: 'Technical Director',
  rigger: 'Rigger',
  carpenter: 'Carpenter',
  electrician: 'Electrician',
  other: 'Other'
};

export default function CrewUtilizationReport({ productionId, dateRange }) {
  const { data: crewMembers = [], isLoading: crewLoading } = useQuery({
    queryKey: ['crewMembers'],
    queryFn: () => base44.entities.CrewMember.list(),
  });

  const { data: assignments = [], isLoading: assignLoading } = useQuery({
    queryKey: ['crewAssignments'],
    queryFn: () => base44.entities.CrewAssignment.list(),
  });

  const { data: productions = [] } = useQuery({
    queryKey: ['productions'],
    queryFn: () => base44.entities.Production.list(),
  });

  const isLoading = crewLoading || assignLoading;

  // Filter assignments by production if selected
  const filteredAssignments = productionId && productionId !== 'all'
    ? assignments.filter(a => a.production_id === productionId)
    : assignments;

  // Calculate stats
  const activeCrewCount = crewMembers.filter(c => c.status === 'active').length;
  const assignedCrewIds = [...new Set(filteredAssignments.map(a => a.crew_member_id).filter(Boolean))];
  const assignedCount = assignedCrewIds.length;
  const unassignedCount = activeCrewCount - assignedCount;

  // Assignments by role
  const roleData = Object.entries(
    filteredAssignments.reduce((acc, a) => {
      acc[a.role] = (acc[a.role] || 0) + 1;
      return acc;
    }, {})
  ).map(([role, count], idx) => ({
    name: roleLabels[role] || role,
    value: count,
    color: COLORS[idx % COLORS.length]
  }));

  // Crew workload (assignments per crew member)
  const workloadData = crewMembers
    .filter(c => c.status === 'active')
    .map(crew => {
      const crewAssignments = filteredAssignments.filter(a => a.crew_member_id === crew.id);
      return {
        name: crew.full_name?.substring(0, 15) || 'Unknown',
        assignments: crewAssignments.length,
        active: crewAssignments.filter(a => a.status === 'active' || a.status === 'confirmed').length
      };
    })
    .sort((a, b) => b.assignments - a.assignments)
    .slice(0, 10);

  // Availability stats
  const availabilityStats = {
    active: crewMembers.filter(c => c.status === 'active').length,
    inactive: crewMembers.filter(c => c.status === 'inactive').length,
    onLeave: crewMembers.filter(c => c.status === 'on_leave').length
  };

  // CSV columns
  const csvColumns = [
    { header: 'Name', key: 'full_name' },
    { header: 'Email', key: 'email' },
    { header: 'Primary Role', accessor: (c) => roleLabels[c.primary_role] || c.primary_role },
    { header: 'Status', key: 'status' },
    { header: 'Hourly Rate', key: 'hourly_rate' },
    { header: 'Total Assignments', accessor: (c) => assignments.filter(a => a.crew_member_id === c.id).length },
  ];

  // PDF sections
  const pdfSections = [
    {
      title: 'Crew Summary',
      type: 'summary',
      items: [
        { label: 'Total Crew Members', value: crewMembers.length },
        { label: 'Active', value: availabilityStats.active },
        { label: 'Inactive', value: availabilityStats.inactive },
        { label: 'On Leave', value: availabilityStats.onLeave },
        { label: 'Currently Assigned', value: assignedCount },
        { label: 'Utilization Rate', value: `${activeCrewCount > 0 ? Math.round((assignedCount / activeCrewCount) * 100) : 0}%` },
      ]
    },
    {
      title: 'Assignments by Role',
      type: 'summary',
      items: roleData.map(r => ({ label: r.name, value: r.value }))
    },
    {
      title: 'Crew Details',
      type: 'table',
      columns: csvColumns.map(c => ({ ...c, width: 30 })),
      data: crewMembers
    }
  ];

  if (isLoading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-slate-400" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Export Button */}
      <div className="flex justify-end">
        <ReportExporter
          title="Crew Utilization Report"
          csvData={crewMembers}
          csvColumns={csvColumns}
          pdfSections={pdfSections}
          filename="crew_utilization"
        />
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-purple-100">
                <Users className="w-5 h-5 text-purple-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">{crewMembers.length}</p>
                <p className="text-xs text-slate-500">Total Crew</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-green-100">
                <UserCheck className="w-5 h-5 text-green-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">{activeCrewCount}</p>
                <p className="text-xs text-slate-500">Active</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-100">
                <Calendar className="w-5 h-5 text-blue-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">{assignedCount}</p>
                <p className="text-xs text-slate-500">Assigned</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-amber-100">
                <Award className="w-5 h-5 text-amber-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">
                  {activeCrewCount > 0 ? Math.round((assignedCount / activeCrewCount) * 100) : 0}%
                </p>
                <p className="text-xs text-slate-500">Utilization</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Assignments by Role</CardTitle>
          </CardHeader>
          <CardContent>
            {roleData.length === 0 ? (
              <p className="text-center py-8 text-slate-500">No assignment data</p>
            ) : (
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={roleData}
                      cx="50%"
                      cy="50%"
                      outerRadius={80}
                      dataKey="value"
                      label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                    >
                      {roleData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Crew Workload (Top 10)</CardTitle>
          </CardHeader>
          <CardContent>
            {workloadData.length === 0 ? (
              <p className="text-center py-8 text-slate-500">No workload data</p>
            ) : (
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={workloadData} layout="vertical">
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis type="number" />
                    <YAxis type="category" dataKey="name" width={100} tick={{ fontSize: 10 }} />
                    <Tooltip />
                    <Bar dataKey="assignments" fill="#8b5cf6" name="Total Assignments" />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Crew Table */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Crew Members</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b">
                  <th className="text-left py-2 px-3">Name</th>
                  <th className="text-left py-2 px-3">Role</th>
                  <th className="text-left py-2 px-3">Status</th>
                  <th className="text-left py-2 px-3">Assignments</th>
                  <th className="text-left py-2 px-3">Rate</th>
                </tr>
              </thead>
              <tbody>
                {crewMembers.slice(0, 10).map(crew => {
                  const crewAssignCount = assignments.filter(a => a.crew_member_id === crew.id).length;
                  return (
                    <tr key={crew.id} className="border-b hover:bg-slate-50">
                      <td className="py-2 px-3 font-medium">{crew.full_name}</td>
                      <td className="py-2 px-3">{roleLabels[crew.primary_role] || crew.primary_role}</td>
                      <td className="py-2 px-3">
                        <Badge variant="outline">{crew.status}</Badge>
                      </td>
                      <td className="py-2 px-3">{crewAssignCount}</td>
                      <td className="py-2 px-3">{crew.hourly_rate ? `$${crew.hourly_rate}/hr` : '-'}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

src/components/reports/EquipmentUsageRep:
import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { format } from 'date-fns';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Loader2, Wrench, Box, Calendar, AlertTriangle } from 'lucide-react';
import ReportExporter from './ReportExporter';

const COLORS = ['#f59e0b', '#3b82f6', '#10b981', '#8b5cf6', '#ef4444', '#ec4899', '#6366f1', '#14b8a6'];

const categoryLabels = {
  lighting: 'Lighting',
  sound: 'Sound',
  rigging: 'Rigging',
  staging: 'Staging',
  video: 'Video',
  props: 'Props',
  tools: 'Tools',
  safety: 'Safety',
  other: 'Other'
};

export default function EquipmentUsageReport({ productionId, dateRange }) {
  const { data: equipment = [], isLoading: equipLoading } = useQuery({
    queryKey: ['equipment'],
    queryFn: () => base44.entities.EquipmentAsset.list(),
  });

  const { data: schedules = [], isLoading: schedLoading } = useQuery({
    queryKey: ['equipmentSchedules'],
    queryFn: () => base44.entities.EquipmentSchedule.list(),
  });

  const { data: maintenance = [], isLoading: maintLoading } = useQuery({
    queryKey: ['maintenanceRecords'],
    queryFn: () => base44.entities.MaintenanceRecord.list(),
  });

  const { data: productions = [] } = useQuery({
    queryKey: ['productions'],
    queryFn: () => base44.entities.Production.list(),
  });

  const isLoading = equipLoading || schedLoading || maintLoading;

  // Filter schedules by production if selected
  const filteredSchedules = productionId && productionId !== 'all'
    ? schedules.filter(s => s.production_id === productionId)
    : schedules;

  // Calculate stats
  const totalEquipment = equipment.length;
  const availableCount = equipment.filter(e => e.status === 'available').length;
  const inUseCount = equipment.filter(e => e.status === 'in_use').length;
  const maintenanceCount = equipment.filter(e => e.status === 'maintenance').length;

  // Equipment by category
  const categoryData = Object.entries(
    equipment.reduce((acc, e) => {
      acc[e.category] = (acc[e.category] || 0) + 1;
      return acc;
    }, {})
  ).map(([cat, count], idx) => ({
    name: categoryLabels[cat] || cat,
    value: count,
    color: COLORS[idx % COLORS.length]
  }));

  // Usage frequency (how many times each piece has been scheduled)
  const usageData = equipment
    .map(eq => {
      const eqSchedules = filteredSchedules.filter(s => s.asset_id === eq.id);
      return {
        name: eq.asset_name?.substring(0, 15) || 'Unknown',
        bookings: eqSchedules.length,
        category: categoryLabels[eq.category] || eq.category
      };
    })
    .sort((a, b) => b.bookings - a.bookings)
    .slice(0, 10);

  // Maintenance by type
  const maintenanceData = Object.entries(
    maintenance.reduce((acc, m) => {
      acc[m.maintenance_type] = (acc[m.maintenance_type] || 0) + 1;
      return acc;
    }, {})
  ).map(([type, count]) => ({
    name: type.charAt(0).toUpperCase() + type.slice(1),
    count
  }));

  // CSV columns
  const csvColumns = [
    { header: 'Asset Name', key: 'asset_name' },
    { header: 'Category', accessor: (e) => categoryLabels[e.category] || e.category },
    { header: 'Status', key: 'status' },
    { header: 'Serial Number', key: 'serial_number' },
    { header: 'Total Bookings', accessor: (e) => schedules.filter(s => s.asset_id === e.id).length },
    { header: 'Maintenance Records', accessor: (e) => maintenance.filter(m => m.asset_id === e.id).length },
  ];

  // PDF sections
  const pdfSections = [
    {
      title: 'Equipment Summary',
      type: 'summary',
      items: [
        { label: 'Total Equipment', value: totalEquipment },
        { label: 'Available', value: availableCount },
        { label: 'In Use', value: inUseCount },
        { label: 'Under Maintenance', value: maintenanceCount },
        { label: 'Availability Rate', value: `${totalEquipment > 0 ? Math.round((availableCount / totalEquipment) * 100) : 0}%` },
      ]
    },
    {
      title: 'Equipment by Category',
      type: 'summary',
      items: categoryData.map(c => ({ label: c.name, value: c.value }))
    },
    {
      title: 'Equipment Details',
      type: 'table',
      columns: csvColumns.map(c => ({ ...c, width: 30 })),
      data: equipment
    }
  ];

  if (isLoading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-slate-400" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Export Button */}
      <div className="flex justify-end">
        <ReportExporter
          title="Equipment Usage Report"
          csvData={equipment}
          csvColumns={csvColumns}
          pdfSections={pdfSections}
          filename="equipment_usage"
        />
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-amber-100">
                <Box className="w-5 h-5 text-amber-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">{totalEquipment}</p>
                <p className="text-xs text-slate-500">Total Assets</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-green-100">
                <Box className="w-5 h-5 text-green-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">{availableCount}</p>
                <p className="text-xs text-slate-500">Available</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-100">
                <Calendar className="w-5 h-5 text-blue-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">{inUseCount}</p>
                <p className="text-xs text-slate-500">In Use</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-red-100">
                <Wrench className="w-5 h-5 text-red-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">{maintenanceCount}</p>
                <p className="text-xs text-slate-500">Maintenance</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Equipment by Category</CardTitle>
          </CardHeader>
          <CardContent>
            {categoryData.length === 0 ? (
              <p className="text-center py-8 text-slate-500">No equipment data</p>
            ) : (
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={categoryData}
                      cx="50%"
                      cy="50%"
                      outerRadius={80}
                      dataKey="value"
                      label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                    >
                      {categoryData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Most Used Equipment</CardTitle>
          </CardHeader>
          <CardContent>
            {usageData.length === 0 ? (
              <p className="text-center py-8 text-slate-500">No usage data</p>
            ) : (
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={usageData} layout="vertical">
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis type="number" />
                    <YAxis type="category" dataKey="name" width={100} tick={{ fontSize: 10 }} />
                    <Tooltip />
                    <Bar dataKey="bookings" fill="#f59e0b" name="Bookings" />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Maintenance History */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Maintenance History</CardTitle>
        </CardHeader>
        <CardContent>
          {maintenanceData.length === 0 ? (
            <p className="text-center py-8 text-slate-500">No maintenance records</p>
          ) : (
            <div className="h-48">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={maintenanceData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="name" />
                  <YAxis />
                  <Tooltip />
                  <Bar dataKey="count" fill="#ef4444" name="Records" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Equipment Table */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Equipment Assets</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b">
                  <th className="text-left py-2 px-3">Asset</th>
                  <th className="text-left py-2 px-3">Category</th>
                  <th className="text-left py-2 px-3">Status</th>
                  <th className="text-left py-2 px-3">Bookings</th>
                  <th className="text-left py-2 px-3">Maintenance</th>
                </tr>
              </thead>
              <tbody>
                {equipment.slice(0, 10).map(eq => {
                  const bookings = schedules.filter(s => s.asset_id === eq.id).length;
                  const maint = maintenance.filter(m => m.asset_id === eq.id).length;
                  return (
                    <tr key={eq.id} className="border-b hover:bg-slate-50">
                      <td className="py-2 px-3 font-medium">{eq.asset_name}</td>
                      <td className="py-2 px-3">{categoryLabels[eq.category] || eq.category}</td>
                      <td className="py-2 px-3">
                        <Badge variant="outline">{eq.status}</Badge>
                      </td>
                      <td className="py-2 px-3">{bookings}</td>
                      <td className="py-2 px-3">{maint}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

src/components/reports/ProductionProgres:
import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { format } from 'date-fns';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Loader2, CheckCircle2, AlertTriangle, Clock, ListTodo } from 'lucide-react';
import ReportExporter from './ReportExporter';

const COLORS = ['#10b981', '#3b82f6', '#f59e0b', '#ef4444'];

export default function ProductionProgressReport({ productionId, dateRange }) {
  const { data: productions = [], isLoading: prodLoading } = useQuery({
    queryKey: ['productions'],
    queryFn: () => base44.entities.Production.list(),
  });

  const { data: allTasks = [], isLoading: tasksLoading } = useQuery({
    queryKey: ['allTasks'],
    queryFn: () => base44.entities.TaskChecklist.list(),
  });

  const { data: allIncidents = [], isLoading: incidentsLoading } = useQuery({
    queryKey: ['allIncidents'],
    queryFn: () => base44.entities.IncidentLog.list(),
  });

  const isLoading = prodLoading || tasksLoading || incidentsLoading;

  // Filter by production if selected
  const filteredProductions = productionId && productionId !== 'all'
    ? productions.filter(p => p.id === productionId)
    : productions;

  const tasks = productionId && productionId !== 'all'
    ? allTasks.filter(t => t.production_id === productionId)
    : allTasks;

  const incidents = productionId && productionId !== 'all'
    ? allIncidents.filter(i => i.production_id === productionId)
    : allIncidents;

  // Calculate stats
  const taskStats = {
    total: tasks.length,
    completed: tasks.filter(t => t.completion_status === 'completed').length,
    inProgress: tasks.filter(t => t.completion_status === 'in_progress').length,
    pending: tasks.filter(t => t.completion_status === 'pending').length,
    blocked: tasks.filter(t => t.completion_status === 'blocked').length,
  };

  const incidentStats = {
    total: incidents.length,
    open: incidents.filter(i => i.resolution_status === 'open').length,
    investigating: incidents.filter(i => i.resolution_status === 'investigating').length,
    resolved: incidents.filter(i => i.resolution_status === 'resolved').length,
    closed: incidents.filter(i => i.resolution_status === 'closed').length,
  };

  const taskChartData = [
    { name: 'Completed', value: taskStats.completed, color: '#10b981' },
    { name: 'In Progress', value: taskStats.inProgress, color: '#3b82f6' },
    { name: 'Pending', value: taskStats.pending, color: '#f59e0b' },
    { name: 'Blocked', value: taskStats.blocked, color: '#ef4444' },
  ].filter(d => d.value > 0);

  const productionTaskData = filteredProductions.map(prod => {
    const prodTasks = allTasks.filter(t => t.production_id === prod.id);
    return {
      name: prod.name.substring(0, 15),
      Completed: prodTasks.filter(t => t.completion_status === 'completed').length,
      'In Progress': prodTasks.filter(t => t.completion_status === 'in_progress').length,
