              <div>
                <p className="text-2xl font-bold">
                  {taskStats.total > 0 ? Math.round((taskStats.completed / taskStats.total) * 100) : 0}%
                </p>
                <p className="text-xs text-slate-500">Completion Rate</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
