import React, { useState, useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { Link } from 'react-router-dom';
import { createPageUrl } from '../utils';
import {
  Theater, Calendar, Clock, CheckCircle2, Loader2, 
  AlertCircle, Users, Filter
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from '@/components/ui/select';
import { format, isPast, isFuture, isToday } from 'date-fns';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';

const statusColors = {
  assigned: 'bg-slate-100 text-slate-700',
  confirmed: 'bg-blue-100 text-blue-700',
  active: 'bg-green-100 text-green-700',
  completed: 'bg-purple-100 text-purple-700',
  cancelled: 'bg-red-100 text-red-700',
};

const roleLabels = {
  stage_manager: 'Stage Manager',
  lighting: 'Lighting',
  sound: 'Sound',
  props: 'Props',
  wardrobe: 'Wardrobe',
  set: 'Set',
  technical_director: 'Technical Director',
  rigger: 'Rigger',
  carpenter: 'Carpenter',
  electrician: 'Electrician',
  other: 'Other',
};

const COLORS = ['#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

export default function MyAssignments() {
  const [currentUser, setCurrentUser] = useState(null);
  const [statusFilter, setStatusFilter] = useState('active');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchUser = async () => {
      const user = await base44.auth.me();
      setCurrentUser(user);
      setLoading(false);
    };
    fetchUser();
  }, []);

  // Find the crew member record for current user
  const { data: crewMember } = useQuery({
    queryKey: ['myCrewMember', currentUser?.email],
    queryFn: () => base44.entities.CrewMember.filter({ email: currentUser.email }),
    select: (data) => data[0],
    enabled: !!currentUser?.email,
  });

  // Get all assignments for this crew member
  const { data: assignments = [], isLoading: assignmentsLoading } = useQuery({
    queryKey: ['myAssignments', crewMember?.id],
    queryFn: () => base44.entities.CrewAssignment.filter({ crew_member_id: crewMember.id }),
    enabled: !!crewMember?.id,
  });

  const { data: productions = [] } = useQuery({
    queryKey: ['productions'],
    queryFn: () => base44.entities.Production.list(),
  });

  const getProduction = (prodId) => productions.find(p => p.id === prodId);

  if (loading || assignmentsLoading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-slate-400" />
      </div>
    );
  }

  if (!crewMember) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <Users className="w-16 h-16 text-slate-300 mb-4" />
        <h2 className="text-xl font-semibold text-slate-900 mb-2">No Crew Profile Found</h2>
        <p className="text-slate-500 text-center max-w-md">
          Your email ({currentUser?.email}) is not linked to a crew member profile. 
          Please contact an administrator to set up your profile.
        </p>
      </div>
    );
  }

  // Filter assignments
  const filteredAssignments = assignments.filter(a => {
    if (statusFilter === 'active') return ['assigned', 'confirmed', 'active'].includes(a.status);
    if (statusFilter === 'completed') return a.status === 'completed';
    if (statusFilter === 'all') return true;
    return a.status === statusFilter;
  });

  // Stats
  const activeCount = assignments.filter(a => ['assigned', 'confirmed', 'active'].includes(a.status)).length;
  const completedCount = assignments.filter(a => a.status === 'completed').length;

  // Role distribution chart data
  const roleDistribution = assignments.reduce((acc, a) => {
    acc[a.role] = (acc[a.role] || 0) + 1;
    return acc;
  }, {});

  const roleChartData = Object.entries(roleDistribution).map(([role, count]) => ({
    name: roleLabels[role] || role,
    value: count,
  }));

  // Status chart data
  const statusChartData = [
    { name: 'Active', value: activeCount, color: '#10b981' },
    { name: 'Completed', value: completedCount, color: '#8b5cf6' },
    { name: 'Cancelled', value: assignments.filter(a => a.status === 'cancelled').length, color: '#ef4444' },
  ].filter(d => d.value > 0);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="w-14 h-14 rounded-full bg-indigo-100 flex items-center justify-center">
            <span className="text-xl font-bold text-indigo-600">
              {crewMember.full_name?.charAt(0)?.toUpperCase()}
            </span>
          </div>
          <div>
            <h1 className="text-2xl font-bold text-slate-900">My Assignments</h1>
            <p className="text-slate-500">{crewMember.full_name} • {roleLabels[crewMember.primary_role]}</p>
          </div>
        </div>
        <Link to={createPageUrl(`CrewMemberDetail?id=${crewMember.id}`)}>
          <Button variant="outline">View Full Profile</Button>
        </Link>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-green-100">
                <CheckCircle2 className="w-5 h-5 text-green-600" />
              </div>
              <div>
                <p className="text-2xl font-bold text-slate-900">{activeCount}</p>
                <p className="text-xs text-slate-500">Active Assignments</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-purple-100">
                <Theater className="w-5 h-5 text-purple-600" />
              </div>
              <div>
                <p className="text-2xl font-bold text-slate-900">{completedCount}</p>
                <p className="text-xs text-slate-500">Completed</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-100">
                <Users className="w-5 h-5 text-blue-600" />
              </div>
              <div>
                <p className="text-2xl font-bold text-slate-900">{assignments.length}</p>
                <p className="text-xs text-slate-500">Total Assignments</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-amber-100">
                <Clock className="w-5 h-5 text-amber-600" />
              </div>
              <div>
                <p className="text-2xl font-bold text-slate-900">{Object.keys(roleDistribution).length}</p>
                <p className="text-xs text-slate-500">Different Roles</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Charts Row */}
      {assignments.length > 0 && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">Assignments by Role</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="h-48">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={roleChartData} layout="vertical">
                    <XAxis type="number" hide />
                    <YAxis type="category" dataKey="name" width={100} tick={{ fontSize: 12 }} />
                    <Tooltip />
                    <Bar dataKey="value" fill="#6366f1" radius={[0, 4, 4, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="text-lg">Assignment Status</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center gap-6">
                <div className="w-32 h-32">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={statusChartData}
                        cx="50%"
                        cy="50%"
                        innerRadius={25}
                        outerRadius={50}
                        dataKey="value"
                      >
                        {statusChartData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={entry.color} />
                        ))}
                      </Pie>
                    </PieChart>
                  </ResponsiveContainer>
                </div>
                <div className="flex-1 space-y-2">
                  {statusChartData.map((item) => (
                    <div key={item.name} className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: item.color }} />
                        <span className="text-sm text-slate-600">{item.name}</span>
                      </div>
                      <span className="font-medium">{item.value}</span>
                    </div>
                  ))}
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Assignments List */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle className="text-lg">Assignments</CardTitle>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-36">
              <Filter className="w-4 h-4 mr-2" />
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="active">Active</SelectItem>
              <SelectItem value="completed">Completed</SelectItem>
              <SelectItem value="all">All</SelectItem>
            </SelectContent>
          </Select>
        </CardHeader>
        <CardContent>
          {filteredAssignments.length === 0 ? (
            <div className="text-center py-8 text-slate-500">
              <Theater className="w-10 h-10 mx-auto mb-2 text-slate-300" />
              <p>No assignments found</p>
            </div>
          ) : (
            <div className="space-y-3">
              {filteredAssignments.map((assignment) => {
                const production = getProduction(assignment.production_id);
                const isUpcoming = assignment.start_date && isFuture(new Date(assignment.start_date));
                const isOngoing = assignment.start_date && assignment.end_date && 
                  isPast(new Date(assignment.start_date)) && isFuture(new Date(assignment.end_date));

                return (
                  <div key={assignment.id} className="p-4 bg-slate-50 rounded-lg">
                    <div className="flex items-start justify-between">
                      <div className="flex items-start gap-3">
                        <div className={`p-2 rounded-lg ${
                          isOngoing ? 'bg-green-100' : isUpcoming ? 'bg-blue-100' : 'bg-slate-100'
                        }`}>
                          <Theater className={`w-5 h-5 ${
                            isOngoing ? 'text-green-600' : isUpcoming ? 'text-blue-600' : 'text-slate-600'
                          }`} />
                        </div>
                        <div>
                          <Link 
                            to={createPageUrl(`ProductionDashboard?id=${assignment.production_id}`)}
                            className="font-semibold text-slate-900 hover:text-blue-600"
                          >
                            {production?.name || 'Unknown Production'}
                          </Link>
                          <p className="text-sm text-slate-500">{roleLabels[assignment.role]}</p>
                          {(assignment.start_date || assignment.end_date) && (
                            <p className="text-xs text-slate-400 mt-1 flex items-center gap-1">
                              <Calendar className="w-3 h-3" />
                              {assignment.start_date && format(new Date(assignment.start_date), 'MMM d, yyyy')}
                              {assignment.end_date && ` - ${format(new Date(assignment.end_date), 'MMM d, yyyy')}`}
                            </p>
                          )}
                          {assignment.notes && (
                            <p className="text-xs text-slate-500 mt-2">{assignment.notes}</p>
                          )}
                        </div>
                      </div>
                      <div className="flex flex-col items-end gap-2">
                        <Badge className={statusColors[assignment.status]}>{assignment.status}</Badge>
                        {isOngoing && <Badge className="bg-green-100 text-green-700">Ongoing</Badge>}
                        {isUpcoming && <Badge className="bg-blue-100 text-blue-700">Upcoming</Badge>}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

src/pages/NotificationSettings.jsx:
import React, { useState, useEffect } from 'react';
import { base44 } from '@/api/base44Client';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { Bell, AtSign, AlertTriangle, ClipboardList, Clapperboard, MessageSquare, Loader2 } from 'lucide-react';
import { toast } from 'sonner';

const notificationTypes = [
  { key: 'mention_enabled', label: 'Mentions', description: 'When someone @mentions you', icon: AtSign },
  { key: 'incident_enabled', label: 'New Incidents', description: 'When a new incident is created', icon: AlertTriangle },
  { key: 'task_overdue_enabled', label: 'Overdue Tasks', description: 'When your tasks become overdue', icon: ClipboardList },
  { key: 'task_assigned_enabled', label: 'Task Assignments', description: 'When a task is assigned to you', icon: ClipboardList },
  { key: 'production_status_enabled', label: 'Production Status', description: 'When production status changes', icon: Clapperboard },
  { key: 'message_enabled', label: 'Messages', description: 'When you receive new messages', icon: MessageSquare },
];

export default function NotificationSettings() {
  const [currentUser, setCurrentUser] = useState(null);
  const [preferences, setPreferences] = useState({
    mention_enabled: true,
    incident_enabled: true,
    task_overdue_enabled: true,
    task_assigned_enabled: true,
    production_status_enabled: true,
    message_enabled: true
  });
  const queryClient = useQueryClient();

  useEffect(() => {
    base44.auth.me().then(setCurrentUser).catch(() => {});
  }, []);

  const { data: existingPrefs, isLoading } = useQuery({
    queryKey: ['notificationPrefs', currentUser?.email],
    queryFn: () => base44.entities.NotificationPreference.filter({ user_email: currentUser?.email }),
    enabled: !!currentUser?.email
  });

  useEffect(() => {
    if (existingPrefs && existingPrefs[0]) {
      setPreferences({
        mention_enabled: existingPrefs[0].mention_enabled ?? true,
        incident_enabled: existingPrefs[0].incident_enabled ?? true,
        task_overdue_enabled: existingPrefs[0].task_overdue_enabled ?? true,
        task_assigned_enabled: existingPrefs[0].task_assigned_enabled ?? true,
        production_status_enabled: existingPrefs[0].production_status_enabled ?? true,
        message_enabled: existingPrefs[0].message_enabled ?? true
      });
    }
  }, [existingPrefs]);

  const saveMutation = useMutation({
    mutationFn: async (prefs) => {
      if (existingPrefs && existingPrefs[0]) {
        return base44.entities.NotificationPreference.update(existingPrefs[0].id, prefs);
      } else {
        return base44.entities.NotificationPreference.create({
          user_email: currentUser.email,
          ...prefs
        });
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['notificationPrefs'] });
      toast.success('Notification preferences saved');
    }
  });

  const handleToggle = (key) => {
    setPreferences(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleSave = () => {
    saveMutation.mutate(preferences);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="p-6 max-w-2xl mx-auto">
      <div className="mb-6">
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <Bell className="h-6 w-6" />
          Notification Settings
        </h1>
        <p className="text-muted-foreground mt-1">
          Control which notifications you receive
        </p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>In-App Notifications</CardTitle>
          <CardDescription>
            Choose which events trigger notifications in your notification bell
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {notificationTypes.map(({ key, label, description, icon: Icon }) => (
            <div key={key} className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-muted rounded-lg">
                  <Icon className="h-4 w-4 text-muted-foreground" />
                </div>
                <div>
                  <Label htmlFor={key} className="font-medium cursor-pointer">
                    {label}
                  </Label>
                  <p className="text-sm text-muted-foreground">{description}</p>
                </div>
              </div>
              <Switch
                id={key}
                checked={preferences[key]}
                onCheckedChange={() => handleToggle(key)}
              />
            </div>
          ))}

          <div className="pt-4 border-t">
            <Button onClick={handleSave} disabled={saveMutation.isPending}>
              {saveMutation.isPending ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Saving...
                </>
              ) : (
                'Save Preferences'
              )}
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

src/pages/Procedures.jsx:
import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { 
  FileText, 
  Plus, 
  Search, 
  MoreVertical,
  Pencil,
  Trash2,
  Loader2,
  Calendar,
  AlertTriangle
} from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { format, differenceInDays } from 'date-fns';
import ProcedureForm from '@/components/procedures/ProcedureForm';

const categoryColors = {
  safety: 'bg-red-100 text-red-700',
  technical: 'bg-purple-100 text-purple-700',
  operational: 'bg-blue-100 text-blue-700',
  emergency: 'bg-orange-100 text-orange-700',
  maintenance: 'bg-amber-100 text-amber-700',
  setup: 'bg-green-100 text-green-700',
  teardown: 'bg-teal-100 text-teal-700',
};

const categoryLabels = {
  safety: 'Safety',
  technical: 'Technical',
  operational: 'Operational',
  emergency: 'Emergency',
  maintenance: 'Maintenance',
  setup: 'Setup',
  teardown: 'Teardown',
};

export default function Procedures() {
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [showForm, setShowForm] = useState(false);
  const [editingProcedure, setEditingProcedure] = useState(null);

  const queryClient = useQueryClient();

  const { data: procedures = [], isLoading } = useQuery({
    queryKey: ['procedures'],
    queryFn: () => base44.entities.ProcedureLibrary.list('-updated_date'),
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => base44.entities.ProcedureLibrary.delete(id),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['procedures'] }),
  });

  const filteredProcedures = procedures.filter(proc => {
    const matchesSearch = 
      proc.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      proc.description?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = categoryFilter === 'all' || proc.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  const isOverdueForReview = (lastReviewedDate) => {
    if (!lastReviewedDate) return true;
    return differenceInDays(new Date(), new Date(lastReviewedDate)) > 365;
  };

  const handleEdit = (procedure) => {
    setEditingProcedure(procedure);
    setShowForm(true);
  };

  const handleCloseForm = () => {
    setShowForm(false);
    setEditingProcedure(null);
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Procedure Library</h1>
          <p className="text-slate-500">Standard operating procedures</p>
        </div>
        <Button onClick={() => setShowForm(true)} className="bg-blue-600 hover:bg-blue-700">
          <Plus className="w-4 h-4 mr-2" />
          Add Procedure
        </Button>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
          <Input
            placeholder="Search procedures..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10"
          />
        </div>
        <Select value={categoryFilter} onValueChange={setCategoryFilter}>
          <SelectTrigger className="w-full sm:w-40">
            <SelectValue placeholder="Category" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Categories</SelectItem>
            {Object.entries(categoryLabels).map(([value, label]) => (
              <SelectItem key={value} value={value}>{label}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Procedures List */}
      {isLoading ? (
        <div className="flex justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-slate-400" />
        </div>
      ) : filteredProcedures.length === 0 ? (
        <Card>
          <CardContent className="flex flex-col items-center justify-center py-12">
            <FileText className="w-12 h-12 text-slate-300 mb-4" />
            <h3 className="text-lg font-medium text-slate-900 mb-1">No procedures found</h3>
            <p className="text-slate-500 mb-4">
              {searchTerm || categoryFilter !== 'all'
                ? 'Try adjusting your filters' 
                : 'Create your first procedure'}
            </p>
            {!searchTerm && categoryFilter === 'all' && (
              <Button onClick={() => setShowForm(true)}>
                <Plus className="w-4 h-4 mr-2" />
                Add Procedure
              </Button>
            )}
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          {filteredProcedures.map((procedure) => (
            <Card key={procedure.id} className="hover:shadow-sm transition-shadow">
              <CardContent className="p-4">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex items-start gap-3 flex-1">
                    <div className={`p-2 rounded-lg ${
                      procedure.category === 'safety' ? 'bg-red-100' :
                      procedure.category === 'emergency' ? 'bg-orange-100' : 'bg-blue-100'
                    }`}>
                      <FileText className={`w-5 h-5 ${
                        procedure.category === 'safety' ? 'text-red-600' :
                        procedure.category === 'emergency' ? 'text-orange-600' : 'text-blue-600'
                      }`} />
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2 flex-wrap">
                        <h3 className="font-semibold text-slate-900">{procedure.title}</h3>
                        <Badge className={categoryColors[procedure.category]}>
                          {categoryLabels[procedure.category]}
                        </Badge>
                        {isOverdueForReview(procedure.last_reviewed_date) && (
                          <Badge variant="outline" className="text-amber-600 border-amber-300">
                            <AlertTriangle className="w-3 h-3 mr-1" />
                            Needs Review
                          </Badge>
                        )}
                      </div>
                      {procedure.description && (
                        <p className="text-sm text-slate-600 mt-1 line-clamp-2">{procedure.description}</p>
                      )}
                      <div className="flex items-center gap-4 mt-2 text-xs text-slate-500">
                        <span>Version {procedure.version || 1}</span>
                        {procedure.last_reviewed_date && (
                          <span className="flex items-center gap-1">
                            <Calendar className="w-3 h-3" />
                            Reviewed: {format(new Date(procedure.last_reviewed_date), 'MMM d, yyyy')}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="icon" className="h-8 w-8">
                        <MoreVertical className="w-4 h-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuItem onClick={() => handleEdit(procedure)}>
                        <Pencil className="w-4 h-4 mr-2" />
                        Edit
                      </DropdownMenuItem>
                      <DropdownMenuItem 
                        onClick={() => deleteMutation.mutate(procedure.id)}
                        className="text-red-600"
                      >
                        <Trash2 className="w-4 h-4 mr-2" />
                        Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <ProcedureForm
        open={showForm}
        onClose={handleCloseForm}
        procedure={editingProcedure}
      />
    </div>
  );
}

src/pages/ProductionCalendar.jsx:
import React, { useState, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Calendar, ChevronLeft, ChevronRight, Download, Loader2, Theater, ListTodo, Users } from 'lucide-react';
import { format, startOfMonth, endOfMonth, eachDayOfInterval, isSameMonth, isSameDay, addMonths, subMonths, isWithinInterval, parseISO } from 'date-fns';

const eventTypes = [
  { id: 'productions', label: 'Productions', color: 'bg-blue-500', icon: Theater },
  { id: 'tasks', label: 'Tasks', color: 'bg-purple-500', icon: ListTodo },
  { id: 'crew', label: 'Crew Assignments', color: 'bg-green-500', icon: Users },
];

export default function ProductionCalendar() {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedFilters, setSelectedFilters] = useState(['productions', 'tasks', 'crew']);
  const [selectedDay, setSelectedDay] = useState(null);

  const { data: productions = [], isLoading: loadingProductions } = useQuery({
    queryKey: ['productions'],
    queryFn: () => base44.entities.Production.list(),
  });

  const { data: tasks = [], isLoading: loadingTasks } = useQuery({
    queryKey: ['tasks'],
    queryFn: () => base44.entities.TaskChecklist.list(),
  });

  const { data: crewAssignments = [], isLoading: loadingCrew } = useQuery({
    queryKey: ['crewAssignments'],
    queryFn: () => base44.entities.CrewAssignment.list(),
  });

  const monthStart = startOfMonth(currentDate);
  const monthEnd = endOfMonth(currentDate);
  const monthDays = eachDayOfInterval({ start: monthStart, end: monthEnd });

  const events = useMemo(() => {
    const allEvents = [];

    if (selectedFilters.includes('productions')) {
      productions.forEach(prod => {
        if (prod.start_date || prod.end_date) {
          allEvents.push({
            id: `prod-${prod.id}`,
            type: 'productions',
            title: prod.name,
            startDate: prod.start_date ? parseISO(prod.start_date) : null,
            endDate: prod.end_date ? parseISO(prod.end_date) : null,
            status: prod.status,
            data: prod,
          });
        }
      });
    }

    if (selectedFilters.includes('tasks')) {
      tasks.forEach(task => {
        if (task.due_date) {
          allEvents.push({
            id: `task-${task.id}`,
            type: 'tasks',
            title: task.task_name,
            date: parseISO(task.due_date),
            priority: task.priority,
            data: task,
          });
        }
      });
    }

    if (selectedFilters.includes('crew')) {
      crewAssignments.forEach(crew => {
        if (crew.start_date || crew.end_date) {
          allEvents.push({
            id: `crew-${crew.id}`,
            type: 'crew',
            title: `${crew.crew_member_name} - ${crew.role}`,
            startDate: crew.start_date ? parseISO(crew.start_date) : null,
            endDate: crew.end_date ? parseISO(crew.end_date) : null,
            data: crew,
          });
        }
      });
    }

    return allEvents;
  }, [productions, tasks, crewAssignments, selectedFilters]);

  const getEventsForDay = (day) => {
    return events.filter(event => {
      if (event.date) {
        return isSameDay(event.date, day);
      }
      if (event.startDate && event.endDate) {
        return isWithinInterval(day, { start: event.startDate, end: event.endDate });
      }
      if (event.startDate) {
        return isSameDay(event.startDate, day);
      }
      return false;
    });
  };

  const handleExport = () => {
    const csvData = events.map(e => ({
      Type: e.type,
      Title: e.title,
      Date: e.date ? format(e.date, 'yyyy-MM-dd') : `${e.startDate ? format(e.startDate, 'yyyy-MM-dd') : ''} - ${e.endDate ? format(e.endDate, 'yyyy-MM-dd') : ''}`,
      Status: e.status || e.priority || '',
    }));

    const csv = [
      Object.keys(csvData[0]).join(','),
      ...csvData.map(row => Object.values(row).join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `calendar-${format(currentDate, 'yyyy-MM')}.csv`;
    a.click();
  };

  const isLoading = loadingProductions || loadingTasks || loadingCrew;

  const dayEvents = selectedDay ? getEventsForDay(selectedDay) : [];

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Production Calendar</h1>
          <p className="text-slate-500">View all production events and schedules</p>
        </div>
        <Button onClick={handleExport} variant="outline">
          <Download className="w-4 h-4 mr-2" />
          Export Calendar
        </Button>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Filter Events</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-4">
            {eventTypes.map(type => {
              const Icon = type.icon;
              return (
                <div key={type.id} className="flex items-center gap-2">
                  <Checkbox
                    id={type.id}
                    checked={selectedFilters.includes(type.id)}
                    onCheckedChange={(checked) => {
                      setSelectedFilters(prev =>
                        checked ? [...prev, type.id] : prev.filter(f => f !== type.id)
                      );
                    }}
                  />
                  <label htmlFor={type.id} className="flex items-center gap-2 cursor-pointer">
                    <div className={`w-3 h-3 rounded ${type.color}`} />
                    <Icon className="w-4 h-4" />
                    <span className="text-sm">{type.label}</span>
                  </label>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Calendar */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <Button variant="outline" size="icon" onClick={() => setCurrentDate(subMonths(currentDate, 1))}>
                <ChevronLeft className="w-4 h-4" />
              </Button>
              <h3 className="text-xl font-semibold">{format(currentDate, 'MMMM yyyy')}</h3>
              <Button variant="outline" size="icon" onClick={() => setCurrentDate(addMonths(currentDate, 1))}>
                <ChevronRight className="w-4 h-4" />
              </Button>
            </div>
            <Button variant="outline" onClick={() => setCurrentDate(new Date())}>
              Today
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="flex justify-center py-12">
              <Loader2 className="w-8 h-8 animate-spin text-slate-400" />
            </div>
          ) : (
            <div className="space-y-4">
              {/* Weekday headers */}
              <div className="grid grid-cols-7 gap-2">
                {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
                  <div key={day} className="text-center text-sm font-medium text-slate-600 py-2">
                    {day}
                  </div>
                ))}
              </div>

              {/* Calendar days */}
              <div className="grid grid-cols-7 gap-2">
                {monthDays.map(day => {
                  const dayEvents = getEventsForDay(day);
                  const isSelected = selectedDay && isSameDay(day, selectedDay);
                  const isToday = isSameDay(day, new Date());

                  return (
                    <div
                      key={day.toString()}
                      onClick={() => setSelectedDay(day)}
                      className={`min-h-24 p-2 border rounded-lg cursor-pointer transition-colors ${
                        isSelected ? 'border-blue-500 bg-blue-50' :
                        isToday ? 'border-blue-300 bg-blue-50/50' :
                        'border-slate-200 hover:bg-slate-50'
                      }`}
                    >
                      <div className={`text-sm font-medium mb-1 ${
                        !isSameMonth(day, currentDate) ? 'text-slate-400' : 'text-slate-900'
                      }`}>
                        {format(day, 'd')}
                      </div>
                      <div className="space-y-1">
                        {dayEvents.slice(0, 3).map(event => {
                          const typeConfig = eventTypes.find(t => t.type === event.type);
                          return (
                            <div
                              key={event.id}
                              className={`text-xs px-1 py-0.5 rounded text-white truncate ${
                                event.type === 'productions' ? 'bg-blue-500' :
                                event.type === 'tasks' ? 'bg-purple-500' : 'bg-green-500'
                              }`}
                              title={event.title}
                            >
                              {event.title}
                            </div>
                          );
                        })}
                        {dayEvents.length > 3 && (
                          <div className="text-xs text-slate-500">+{dayEvents.length - 3} more</div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Selected Day Events */}
      {selectedDay && dayEvents.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">
              Events for {format(selectedDay, 'MMMM d, yyyy')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {dayEvents.map(event => (
                <div key={event.id} className="p-3 border rounded-lg hover:bg-slate-50">
                  <div className="flex items-start justify-between">
                    <div className="flex items-start gap-3">
                      <div className={`w-2 h-2 rounded-full mt-2 ${
                        event.type === 'productions' ? 'bg-blue-500' :
                        event.type === 'tasks' ? 'bg-purple-500' : 'bg-green-500'
                      }`} />
                      <div>
                        <p className="font-medium text-slate-900">{event.title}</p>
                        <p className="text-sm text-slate-500 capitalize">{event.type}</p>
                      </div>
                    </div>
                    {event.status && (
                      <Badge variant="outline">{event.status}</Badge>
                    )}
                    {event.priority && (
                      <Badge variant={event.priority === 'critical' ? 'destructive' : 'outline'}>
                        {event.priority}
                      </Badge>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

