                      <Badge variant={incident.severity === 'critical' ? 'destructive' : 'outline'} className="text-xs flex-shrink-0">
                        {incident.severity}
                      </Badge>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Equipment */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <Box className="w-5 h-5" />
              Equipment Scheduled
            </CardTitle>
