                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Incident Severity Distribution */}
      {incidents.length > 0 && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card>
            <CardHeader>
              <CardTitle className="text-lg flex items-center gap-2">
                <AlertTriangle className="w-5 h-5" />
                Incidents by Severity
