                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie
                            data={severityData}
                            cx="50%"
                            cy="50%"
                            innerRadius={25}
                            outerRadius={50}
                            dataKey="value"
                          >
                            {severityData.map((entry, index) => (
                              <Cell key={`cell-${index}`} fill={entry.color} />
                            ))}
                          </Pie>
                        </PieChart>
                      </ResponsiveContainer>
                    </div>
                    <div className="flex-1 space-y-2">
                      {severityData.map((item) => (
                        <div key={item.name} className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: item.color }} />
                            <span className="text-sm text-slate-600">{item.name}</span>
                          </div>
                          <span className="font-medium">{item.value}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                );
              })()}
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="text-lg flex items-center gap-2">
                <TrendingUp className="w-5 h-5" />
                Equipment by Category
              </CardTitle>
            </CardHeader>
            <CardContent>
              {(() => {
                const scheduledAssetIds = equipmentSchedules.map(s => s.asset_id);
                const scheduledAssets = assets.filter(a => scheduledAssetIds.includes(a.id));
                const categoryData = scheduledAssets.reduce((acc, asset) => {
                  acc[asset.category] = (acc[asset.category] || 0) + 1;
                  return acc;
                }, {});

                const chartData = Object.entries(categoryData).map(([cat, count]) => ({
                  name: cat,
                  count,
                }));

                if (chartData.length === 0) {
                  return <p className="text-center py-4 text-slate-500">No equipment data</p>;
                }

                return (
                  <div className="h-40">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={chartData}>
                        <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                        <YAxis hide />
                        <Tooltip />
                        <Bar dataKey="count" fill="#f59e0b" radius={[4, 4, 0, 0]} />
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                );
              })()}
            </CardContent>
          </Card>
        </div>
      )}

      {/* Budget Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <DollarSign className="w-5 h-5" />
              Budget Management
            </CardTitle>
          </CardHeader>
          <CardContent>
            <BudgetManager productionId={productionId} />
          </CardContent>
        </Card>
        <BudgetChart productionId={productionId} />
      </div>

      {/* Quick Actions */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Quick Actions</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-3">
            <Link to={createPageUrl(`ProductionDetail?id=${productionId}`)}>
              <Button variant="outline">
                <ListTodo className="w-4 h-4 mr-2" />
                Manage Tasks
              </Button>
            </Link>
            <Link to={createPageUrl(`EquipmentScheduling?production_id=${productionId}`)}>
              <Button variant="outline">
                <Box className="w-4 h-4 mr-2" />
                Schedule Equipment
              </Button>
            </Link>
            <Link to={createPageUrl('Incidents')}>
              <Button variant="outline">
                <AlertTriangle className="w-4 h-4 mr-2" />
                Log Incident
              </Button>
            </Link>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

